1	// `andesim run --mode fast|cycle|hybrid [engine selection] ELF [-- engine args]`.
2	//
3	// The top selection axis. F7/F8 land the two standalone models, `fast` (QEMU)
4	// and `cycle` (a cycle-accurate engine, from reset): each resolves its
5	// engine, then hands off to transparent passthrough -- the ELF plus everything
6	// after `--` becomes the engine's own command line, run with inherited stdio,
7	// no timeout, and the exit code propagated, so a gdbstub / monitor /
8	// semihosting console all behave as if the engine were invoked directly.
9	// `hybrid` (F9) lands in a later feature; its dispatch arm stubs for now.
10	#include <cstdio>
11	#include <filesystem>
12	#include <string>
13	#include <vector>
14	
15	#include "cli.hpp"
16	#include "engine_descriptor.hpp"
17	#include "engine_registry.hpp"
18	#include "models.hpp"
19	#include "process.hpp"
20	#include "run_passthrough.hpp"
21	
22	namespace fs = std::filesystem;
23	
24	namespace andes_sim {
25	namespace {
26	
27	// Resolve `path` to an absolute, EXISTING ELF. Returns the resolved string on
28	// success; on failure prints an error tagged with `ctx` and returns "". The
29	// existence check is here, at the shared resolver, so a missing path fails
30	// with a clear "ELF not found" instead of being handed to the engine (e.g.
31	// qemu's cryptic "Unable to find the RISC-V BIOS").
32	std::string abs_elf(const std::string& path, const std::string& ctx) {
33	  std::error_code ec;
34	  fs::path abs = fs::absolute(path, ec);
35	  if (ec) {
36	    std::fprintf(stderr, "andesim run %s: cannot resolve ELF '%s'\n",
37	                 ctx.c_str(), path.c_str());
38	    return "";
39	  }
40	  if (!fs::is_regular_file(abs, ec)) {
41	    std::fprintf(stderr, "andesim run %s: ELF not found: %s\n", ctx.c_str(),
42	                 path.c_str());
43	    return "";
44	  }
45	  return abs.string();
46	}
47	
48	// Validate the lone-ELF positional shape the standalone models require: print
49	// the diagnostic and return 2 on a violation, else 0. `model` labels the error.
50	int check_one_elf(const Cli& cli, const char* model) {
51	  if (cli.positional.empty()) {
52	    std::fprintf(stderr,
53	                 "andesim run --mode %s: missing ELF (the workload to run; "
54	                 "e.g. a tests/fixtures/<name>.elf)\n",
55	                 model);
56	    return 2;
57	  }
58	  if (cli.positional.size() > 1) {
59	    std::fprintf(stderr,
60	                 "andesim run --mode %s: unexpected argument '%s' "
61	                 "(engine args go after --)\n",
62	                 model, cli.positional[1].c_str());
63	    return 2;
64	  }
65	  return 0;
66	}
67	
68	// The standalone spine: take a single ELF, then run the resolved engine
69	// standalone with the post-`--` args appended verbatim (exec_passthrough --
70	// inherit stdio, no timeout, propagate the exit code, so an interactive
71	// gdbstub / monitor / semihosting console works unchanged). The per-model
72	// engine + selection are resolved by the caller; `model` here only labels
73	// the positional diagnostics.
74	int run_standalone(const Cli& cli, const EngineDescriptor& eng,
75	                   const char* model) {
76	  if (int rc = check_one_elf(cli, model)) return rc;
77	  // QEMU's -bios flag searches its data directory for relative paths rather
78	  // than the CWD; resolve to absolute so the engine finds the ELF.
79	  const std::string elf = abs_elf(cli.positional[0], "--mode " + std::string(model));
80	  if (elf.empty()) return 2;
81	  std::string err;
82	  const std::vector<std::string> argv =
83	      passthrough_argv(eng, "standalone", elf, cli.passthrough, err);
84	  if (!err.empty()) {
85	    std::fprintf(stderr, "andesim run: %s\n", err.c_str());
86	    return 2;
87	  }
88	  return exec_passthrough(argv);
89	}
90	
91	// `run --mode fast`: QEMU alone, functional, transparent passthrough. Needs
92	// only the built-in qemu descriptor, so it resolves that directly rather than
93	// discover_engines(), which would spawn a --describe subprocess per Verilator
94	// build only to discard them all here.
95	int run_fast(const Cli& cli) {
96	  // fast is QEMU-only; an explicit engine must name it.
97	  if (!cli.engine.empty() && cli.engine != kQemuId) {
98	    std::fprintf(stderr,
99	                 "andesim run --mode fast: engine must be 'qemu', got '%s'\n",
100	                 cli.engine.c_str());
101	    return 2;
102	  }
103	  return run_standalone(cli, builtin_qemu(), "fast");
104	}
105	
106	// `run --mode cycle`: one cycle-accurate engine alone, from reset (no QEMU,
107	// no --resume-from-qemu), transparent passthrough -- cycles surface in the
108	// engine's own output. Unlike fast, this must discover the vsim build(s) to
109	// resolve the engine (explicit --engine, else the sole one).
110	int run_accurate(const Cli& cli) {
111	  // Reject a missing/extra ELF before discovery so a CLI typo does not spawn a
112	  // --describe subprocess per vsim build only to fail on the argument.
113	  if (int rc = check_one_elf(cli, "cycle")) return rc;
114	  Discovery disc = discover_engines();
115	  std::string err;
116	  const EngineDescriptor* eng =
117	      resolve_accurate_engine(disc.engines, cli.engine, err);
118	  if (!eng) {
119	    std::fprintf(stderr, "andesim run --mode cycle: %s\n", err.c_str());
120	    // Surface why an expected engine may be absent (failed --describe, etc.).
121	    for (const std::string& w : disc.warnings)
122	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
123	    return 2;
124	  }
125	  return run_standalone(cli, *eng, "cycle");
126	}
127	
128	}  // namespace
129	
130	int cmd_run(const Cli& cli) {
131	  if (cli.model.empty()) {
132	    std::fprintf(stderr,
133	                 "andesim run: --mode fast|cycle|hybrid is required "
134	                 "(pick the composition; see 'andesim run --help')\n");
135	    return 2;
136	  }
137	  if (!find_model(cli.model)) {
138	    std::fprintf(stderr,
139	                 "andesim run: unknown model '%s' (want fast|cycle|hybrid)\n",
140	                 cli.model.c_str());
141	    return 2;
142	  }
143	  if (cli.model == "fast") return run_fast(cli);
144	  if (cli.model == "cycle") return run_accurate(cli);
145	
146	  std::fprintf(stderr, "andesim run --mode %s: not yet implemented\n",
147	               cli.model.c_str());
148	  return 3;
149	}
150	
151	}  // namespace andes_sim
