18	const EngineDescriptor* find_engine(const std::vector<EngineDescriptor>& engines,
19	                                    const std::string& id) {
20	  for (const EngineDescriptor& e : engines)
21	    if (e.id == id) return &e;
22	  return nullptr;
23	}
24	
25	}  // namespace
