27	std::vector<std::vector<std::string>> plan_argvs(
28	    const Plan& plan, const std::vector<EngineDescriptor>& engines,
29	    const std::string& workdir, const RuntimeCtx& ctx, std::string& err) {
30	  std::vector<std::vector<std::string>> out;
31	  out.reserve(plan.steps.size());
32	  std::string prev_state_out;  // empty for the cold first leg
33	
34	  for (size_t i = 0; i < plan.steps.size(); ++i) {
35	    const Step& step = plan.steps[i];
36	    const EngineDescriptor* eng = find_engine(engines, step.engine_id);
37	    if (!eng) {
38	      err = "plan step " + std::to_string(i) + ": unknown engine '" +
39	            step.engine_id + "'";
40	      return {};
41	    }
42	    const std::vector<std::string>* tmpl = eng->invoke_for(step.role);
43	    if (!tmpl) {
44	      err = "plan step " + std::to_string(i) + ": engine '" + step.engine_id +
45	            "' has no invoke template for role '" + step.role + "'";
46	      return {};
47	    }
48	
49	    const std::string state_out = state_path(workdir, i);
50	    const std::map<std::string, std::string> m = {
51	        {"bin", eng->bin_path},
52	        {"elf", plan.elf},
53	        {"plugin", ctx.plugin_path},
54	        {"mmap", ctx.mmap_path},
55	        {"mmap_size", std::to_string(ctx.mem_size)},
56	        {"mmap_base", ctx.mmap_base},
57	        {"state_in", prev_state_out},
58	        {"state_out", state_out},
59	    };
60	    std::vector<std::string> argv = build_argv(*tmpl, m, err);
61	    if (!err.empty()) {
62	      err = "plan step " + std::to_string(i) + ": " + err;
63	      return {};
64	    }
65	    out.push_back(std::move(argv));
66	    prev_state_out = state_out;
67	  }
68	  err.clear();
69	  return out;
70	}
