2	// The pure core of `run --mode hybrid`: turn the CLI selection into a Trigger.
3	//
4	// Split out from cmd_run.cpp so it is unit-testable without spawning qemu/vsim.
5	// pc-mode boundaries are resolved against the ELF .symtab here (via elf_syms),
6	// so the live path in cmd_run only has to build the 2-step plan and run it.
7	#ifndef ANDESIM_HYBRID_HPP
8	#define ANDESIM_HYBRID_HPP
9	
10	#include <string>
11	#include <vector>
12	
13	#include "cli.hpp"
14	#include "engine_descriptor.hpp"
15	#include "plan.hpp"
16	
17	namespace andes_sim {
18	
19	// Build the ROI Trigger for a hybrid run from `cli` + `elf` (the ELF is needed
20	// to resolve pc-mode symbol boundaries). The pc boundaries are stored as
21	// "0x"-prefixed hex in params (enter_pc/exit_pc). On a missing/unresolvable pc
22	// boundary or unknown trigger, returns a Trigger with empty kind and sets `err`.
23	Trigger hybrid_trigger(const Cli& cli, const std::string& elf, std::string& err);
24	
25	// Build the vsim accurate-leg's user-forwarded extra args (verbatim tokens
26	// appended after the trigger args): kanata ROI visualization
27	// (`--kanata <f> --kanata-roi [--objdump <f>]`). `kind` is the trigger kind,
28	// used to validate: --kanata is marker/pc only; --objdump requires --kanata.
29	// On a violation returns {} and sets `err`. Absent kanata yields an empty
30	// list (the common case). Post-`--` args are NOT forwarded here -- hybrid
31	// rejects them up front (cmd_run), as the handoff owns both legs' argv.
32	std::vector<std::string> vsim_extra_args(const Cli& cli, const std::string& kind,
33	                                         std::string& err);
34	
35	// ISA-sync guard for the accurate-leg engine: the hybrid fast leg is a 64-bit
36	// QEMU, so an engine reporting xlen != 64 cannot share architectural state
37	// with it. Returns "" when the pairing is valid, else the diagnostic. An
38	// engine that reports no xlen (0) is accepted as-is.
39	std::string hybrid_hw_check(const EngineDescriptor& acc);
40	
41	}  // namespace andes_sim
42	
43	#endif  // ANDESIM_HYBRID_HPP
