45	// See hybrid.hpp. Builds the ROI Trigger from the CLI, resolving pc boundaries.
46	#include "hybrid.hpp"
47	
48	#include <cstdint>
49	
50	#include "elf_syms.hpp"
51	
52	namespace andes_sim {
53	namespace {
54	
55	// Numeric value of a bare-hex PC string from resolve_pc. resolve_pc already
56	// validated the digits; an absurd >64-bit address (out_of_range) yields false,
57	// so the equal-ROI guard simply skips it (the bogus address fails downstream).
58	bool hex_pc(const std::string& s, uint64_t& out) {
59	  try {
60	    std::size_t pos = 0;
61	    out = std::stoull(s, &pos, 16);
62	    return pos == s.size();
63	  } catch (...) {
64	    return false;
65	  }
66	}
67	
68	}  // namespace
69	
70	Trigger hybrid_trigger(const Cli& cli, const std::string& elf,
71	                       std::string& err) {
72	  err.clear();
73	  // --trigger is REQUIRED for hybrid: no silent default. An absent trigger used
74	  // to fall back to marker, which masked running an unmarked ELF (the fast leg
75	  // ran to completion instead of draining at the ROI, surfacing only as a
76	  // cryptic "expected exit 200, got 0"). Make the user name the ROI delimiter.
77	  if (cli.trigger.empty()) {
78	    err = "--trigger marker|pc is required "
79	          "(the ROI delimiter; see 'andesim run --help')";
80	    return {};
81	  }
82	  const std::string kind = cli.trigger;
83	
84	  if (kind == "marker") return {"marker", {}};  // markers in the workload; no params
85	
86	  if (kind == "pc") {
87	    if (cli.pc_start.empty() || cli.pc_end.empty()) {
88	      err = "trigger pc requires --pc-start and --pc-end "
89	            "(a symbol name or 0x address)";
90	      return {};
91	    }
92	    std::string e1, e2;
93	    const std::string enter = resolve_pc(elf, cli.pc_start, e1);
94	    if (!e1.empty()) { err = e1; return {}; }
95	    const std::string exit = resolve_pc(elf, cli.pc_end, e2);
96	    if (!e2.empty()) { err = e2; return {}; }
97	    // A zero-length ROI (enter == exit) is degenerate: vsim resumes at the
98	    // enter PC and the exit trigger fires on that very instruction, so the
99	    // window measures nothing. Compare numerically -- a symbol and its literal
100	    // 0x address (or 0x0001000 vs 0x1000) are different strings, same PC.
101	    uint64_t a_enter = 0, a_exit = 0;
102	    if (hex_pc(enter, a_enter) && hex_pc(exit, a_exit) && a_enter == a_exit) {
103	      err = "trigger pc: --pc-start and --pc-end resolve to the same address "
104	            "0x" + enter + " (an empty ROI measures nothing)";
105	      return {};
106	    }
107	    // Store with the 0x prefix the plugin (enter_pc=0x..) and vsim
108	    // (--hybrid-exit-pc 0x..) expect; leg_trigger_args concatenates verbatim.
109	    return {"pc", {{"enter_pc", "0x" + enter}, {"exit_pc", "0x" + exit}}};
110	  }
111	
112	  err = "unknown trigger '" + kind + "' (want marker|pc)";
113	  return {};
114	}
115	
116	std::string hybrid_hw_check(const EngineDescriptor& acc) {
117	  if (acc.xlen != 0 && acc.xlen != 64)
118	    return "engine " + acc.id + " is rv" + std::to_string(acc.xlen) +
119	           " (xlen=" + std::to_string(acc.xlen) +
120	           "); the hybrid fast leg (QEMU) is rv64-only";
121	  return "";
122	}
123	
124	std::vector<std::string> vsim_extra_args(const Cli& cli, const std::string& kind,
125	                                         std::string& err) {
126	  err.clear();
127	  std::vector<std::string> out;
128	
129	  // kanata ROI visualization first (marker/pc only; objdump rides kanata).
130	  if (!cli.kanata.empty()) {
131	    if (kind != "marker" && kind != "pc") {
132	      err = "--kanata is only supported with trigger marker or pc (got " + kind +
133	            ")";
134	      return {};
135	    }
136	    out.push_back("--kanata");
137	    out.push_back(cli.kanata);
138	    out.push_back("--kanata-roi");
139	    if (!cli.objdump.empty()) {
140	      out.push_back("--objdump");
141	      out.push_back(cli.objdump);
142	    }
143	  } else if (!cli.objdump.empty()) {
144	    err = "--objdump requires --kanata";
145	    return {};
146	  }
147	
148	  return out;
149	}
