152	===== driver/elf_syms.hpp =====
153	// ELF symbol resolution for pc-trigger boundaries (F9).
154	//
155	// pc mode switches QEMU <-> vsim at two PCs. Either boundary may be a
156	// "0x"-prefixed hex address (used verbatim) OR a symbol defined in the ELF
157	// (resolved against its .symtab). This decouples the switch points from the
158	// workload source -- any function can bound the ROI, with no planted markers.
159	//
160	// C++ port of tests/lib/roi.sh:resolve_pc, reading the ELF .symtab directly via
161	// <elf.h> rather than shelling out to `nm`.
162	#ifndef ANDESIM_ELF_SYMS_HPP
163	#define ANDESIM_ELF_SYMS_HPP
164	
165	#include <cstdint>
166	#include <string>
167	
168	namespace andes_sim {
169	
170	// Resolve a pc-mode boundary to a bare hex address string (no "0x" prefix).
171	//   "0x<h>" / "0X<h>"  -> "<h>" verbatim (prefix stripped, digits unchanged)
172	//   <symbol>           -> the symbol's st_value as lowercase hex
173	// On any failure (undefined symbol, unreadable/!ELF file) returns "" and sets
174	// `err` to a message naming the boundary; on success leaves `err` empty.
175	std::string resolve_pc(const std::string& elf_path, const std::string& boundary,
176	                       std::string& err);
177	
178	// The ELF entry point (e_entry) -- the default lock-step arm pc. Returns 0 and
179	// sets `err` on an unreadable / non-RV64 file; clears `err` on success.
180	uint64_t elf_entry(const std::string& elf_path, std::string& err);
181	
182	// The ELF class width in bits from e_ident[EI_CLASS]: 32 (ELFCLASS32) or 64
183	// (ELFCLASS64). Returns 0 when `elf_path` is unreadable or not an ELF. Reads
184	// only the 16-byte e_ident (the class-independent prefix), so it answers for
185	// rv32 and rv64 alike -- the source of truth for the fast auto-pick of
186	// qemu-system-riscv32/64 and the cycle/hybrid arch-match guard.
187	int elf_xlen(const std::string& elf_path);
188	
189	// L26/F3: the highest byte of the ELF's static memory image -- the maximum
190	// (p_paddr + p_memsz) over PT_LOAD segments. The driver rejects a hybrid run
191	// when this exceeds the V-scratch GPA (ram_base + --mem-size): the static image
192	// would extend into the reserved transport page above the program's RAM.
193	// Returns 0 + err on an unreadable / non-ELFCLASS64 file; 0 with empty err when
194	// the ELF has no loadable segments (nothing to clash with the scratch).
195	uint64_t elf_load_top(const std::string& elf_path, std::string& err);
196	
197	// Reverse lookup: the nearest function symbol at or below `addr`, formatted
198	// "name+0xoff" (or just "name" at offset 0). Returns "" when no covering
199	// function symbol is found or the ELF is unreadable -- the caller always has
200	// the raw pc to fall back on, so this never errors.
201	std::string symbolize(const std::string& elf_path, uint64_t addr);
202	
203	// Returns {st_value, st_value + st_size} for the FUNC symbol covering `addr`.
204	// Both members are 0 when not found or unreadable.
205	std::pair<uint64_t, uint64_t> fn_range(const std::string& elf_path, uint64_t addr);
206	
207	}  // namespace andes_sim
208	
209	#endif  // ANDESIM_ELF_SYMS_HPP
