211	// See elf_syms.hpp. Reads the ELF .symtab directly (no `nm` shell-out).
212	#include "elf_syms.hpp"
213	
214	#include <cstdint>
215	#include <cstring>
216	#include <fstream>
217	#include <sstream>
218	#include <vector>
219	
220	#include <elf.h>
221	
222	namespace andes_sim {
223	namespace {
224	
225	// Lowercase, minimal-width hex -- matches the bare hex a stripped "0x" address
226	// yields, so a symbol and its literal address resolve to the same string.
227	std::string to_hex(uint64_t v) {
228	  std::ostringstream ss;
229	  ss << std::hex << v;
230	  return ss.str();
231	}
232	
233	bool slurp(const std::string& path, std::vector<char>& buf) {
234	  std::ifstream f(path, std::ios::binary);
235	  if (!f) return false;
236	  std::ostringstream ss;
237	  ss << f.rdbuf();
238	  const std::string s = ss.str();
239	  buf.assign(s.begin(), s.end());
240	  return true;
241	}
242	
243	// memcpy a POD header out of the buffer at `off`; false if it would overrun
244	// (buffers may be truncated/malformed -- never read past the end).
245	template <class T>
246	bool load(const std::vector<char>& buf, size_t off, T& out) {
247	  if (off + sizeof(T) > buf.size()) return false;
248	  std::memcpy(&out, buf.data() + off, sizeof(T));
249	  return true;
250	}
251	
252	// Slurp `path` and validate its ELFCLASS64 header into `eh`. Returns false and
253	// sets `err` (unreadable / not-ELF / not-RV64) on failure, clears `err` on ok.
254	// Shared prologue for every ELF reader below.
255	bool read_elf64_header(const std::string& path, std::vector<char>& buf,
256	                       Elf64_Ehdr& eh, std::string& err) {
257	  err.clear();
258	  if (!slurp(path, buf)) {
259	    err = "cannot read ELF '" + path + "'";
260	    return false;
261	  }
262	  if (!load(buf, 0, eh) || std::memcmp(eh.e_ident, ELFMAG, SELFMAG) != 0) {
263	    err = "not an ELF file: " + path;
264	    return false;
265	  }
266	  if (eh.e_ident[EI_CLASS] != ELFCLASS64) {
267	    err = "not an RV64 (ELFCLASS64) file: " + path;
268	    return false;
269	  }
270	  return true;
271	}
