275	std::string resolve_pc(const std::string& elf_path, const std::string& boundary,
276	                       std::string& err) {
277	  err.clear();
278	
279	  // A "0x"/"0X" address is used verbatim with the prefix stripped (roi.sh
280	  // `${boundary#0[xX]}`); the .symtab is never touched.
281	  if (boundary.starts_with("0x") || boundary.starts_with("0X")) {
282	    std::string addr = boundary.substr(2);
283	    // Must be all hex digits: a verbatim pass of e.g. "ZZZ"/"10zz" would let the
284	    // downstream strtoull silently truncate to 0x0/0x10 (wrong PC window).
285	    if (addr.empty() ||
286	        addr.find_first_not_of("0123456789abcdefABCDEF") != std::string::npos) {
287	      err = "malformed address '" + boundary + "'";
288	      return "";
289	    }
290	    return addr;
291	  }
292	
293	  std::vector<char> buf;
294	  Elf64_Ehdr eh;
295	  if (!read_elf64_header(elf_path, buf, eh, err)) return "";
296	
297	  // Scan section headers for a symbol table; resolve names through its linked
298	  // string table (sh_link).
299	  for (unsigned i = 0; i < eh.e_shnum; ++i) {
300	    Elf64_Shdr sym_sh;
301	    if (!load(buf, eh.e_shoff + static_cast<size_t>(i) * eh.e_shentsize, sym_sh))
302	      break;
303	    if (sym_sh.sh_type != SHT_SYMTAB || sym_sh.sh_entsize == 0) continue;
304	
305	    Elf64_Shdr str_sh;
306	    if (sym_sh.sh_link >= eh.e_shnum ||
307	        !load(buf, eh.e_shoff + static_cast<size_t>(sym_sh.sh_link) * eh.e_shentsize,
308	              str_sh))
309	      continue;
310	
311	    const size_t nsym = sym_sh.sh_size / sym_sh.sh_entsize;
312	    for (size_t s = 0; s < nsym; ++s) {
313	      Elf64_Sym sym;
314	      if (!load(buf, sym_sh.sh_offset + s * sym_sh.sh_entsize, sym)) break;
315	      if (sym.st_shndx == SHN_UNDEF) continue;  // --defined-only
316	
317	      const size_t noff = str_sh.sh_offset + sym.st_name;
318	      if (noff >= buf.size()) continue;
319	      const char* name = buf.data() + noff;
320	      const size_t avail = buf.size() - noff;
321	      if (::strnlen(name, avail) == avail) continue;  // unterminated in bounds
322	      if (boundary == name) return to_hex(sym.st_value);
323	    }
324	  }
325	
326	  err = "symbol '" + boundary + "' not defined in " + elf_path;
327	  return "";
328	}
