330	uint64_t elf_entry(const std::string& elf_path, std::string& err) {
331	  std::vector<char> buf;
332	  Elf64_Ehdr eh;
333	  if (!read_elf64_header(elf_path, buf, eh, err)) return 0;
334	  return eh.e_entry;
335	}
