337	int elf_xlen(const std::string& elf_path) {
338	  // Only e_ident is needed (16 bytes, identical layout for both classes), so
339	  // read just that rather than slurping a whole (possibly large) ELF.
340	  std::ifstream f(elf_path, std::ios::binary);
341	  unsigned char ident[EI_NIDENT];
342	  if (!f.read(reinterpret_cast<char*>(ident), EI_NIDENT)) return 0;
343	  if (std::memcmp(ident, ELFMAG, SELFMAG) != 0) return 0;  // not an ELF
344	  switch (ident[EI_CLASS]) {
345	    case ELFCLASS32: return 32;
346	    case ELFCLASS64: return 64;
347	    default: return 0;
348	  }
349	}
350	
351	uint64_t elf_load_top(const std::string& elf_path, std::string& err) {
352	  std::vector<char> buf;
353	  Elf64_Ehdr eh;
354	  if (!read_elf64_header(elf_path, buf, eh, err)) return 0;
355	  // Top of the static image: the highest (p_paddr + p_memsz) over PT_LOAD.
356	  // p_paddr is the guest-physical placement (== p_vaddr for the identity-mapped
357	  // bare-metal fixtures), the space the V-scratch GPA also lives in.
358	  uint64_t top = 0;
359	  for (uint16_t i = 0; i < eh.e_phnum; ++i) {
360	    Elf64_Phdr ph;
361	    const size_t off = static_cast<size_t>(eh.e_phoff) +
362	                       static_cast<size_t>(i) * eh.e_phentsize;
363	    if (!load(buf, off, ph)) {
364	      err = "truncated program header table in '" + elf_path + "'";
365	      return 0;
366	    }
367	    if (ph.p_type != PT_LOAD) continue;
368	    const uint64_t end = ph.p_paddr + ph.p_memsz;
369	    if (end > top) top = end;
370	  }
371	  return top;  // 0 (empty err) when the ELF has no loadable segments
372	}
373	
374	std::string symbolize(const std::string& elf_path, uint64_t addr) {
375	  std::vector<char> buf;
376	  Elf64_Ehdr eh;
377	  std::string ignored;  // symbolize never errors -- empty result is the signal
378	  if (!read_elf64_header(elf_path, buf, eh, ignored)) return "";
379	
380	  // Track the highest-valued FUNC symbol whose range covers addr (st_value <=
381	  // addr < st_value + st_size), falling back to the nearest preceding FUNC
382	  // when sizes are absent.
383	  std::string best_name;
384	  uint64_t best_value = 0;
385	  bool found = false;
386	
387	  for (unsigned i = 0; i < eh.e_shnum; ++i) {
388	    Elf64_Shdr sym_sh;
389	    if (!load(buf, eh.e_shoff + static_cast<size_t>(i) * eh.e_shentsize, sym_sh))
390	      break;
391	    if (sym_sh.sh_type != SHT_SYMTAB || sym_sh.sh_entsize == 0) continue;
392	
393	    Elf64_Shdr str_sh;
394	    if (sym_sh.sh_link >= eh.e_shnum ||
395	        !load(buf, eh.e_shoff + static_cast<size_t>(sym_sh.sh_link) * eh.e_shentsize,
396	              str_sh))
397	      continue;
398	
399	    const size_t nsym = sym_sh.sh_size / sym_sh.sh_entsize;
400	    for (size_t s = 0; s < nsym; ++s) {
401	      Elf64_Sym sym;
402	      if (!load(buf, sym_sh.sh_offset + s * sym_sh.sh_entsize, sym)) break;
403	      if (sym.st_shndx == SHN_UNDEF) continue;
404	      if (ELF64_ST_TYPE(sym.st_info) != STT_FUNC) continue;
405	      if (sym.st_value > addr) continue;
406	      // With a size, require coverage; without, accept as a preceding label.
407	      if (sym.st_size != 0 && addr >= sym.st_value + sym.st_size) continue;
408	      if (found && sym.st_value <= best_value) continue;
409	
410	      const size_t noff = str_sh.sh_offset + sym.st_name;
411	      if (noff >= buf.size()) continue;
412	      const char* name = buf.data() + noff;
413	      const size_t avail = buf.size() - noff;
414	      if (::strnlen(name, avail) == avail) continue;
415	
416	      best_name = name;
417	      best_value = sym.st_value;
418	      found = true;
419	    }
420	  }
421	
422	  if (!found) return "";
423	  const uint64_t off = addr - best_value;
424	  if (off == 0) return best_name;
425	  std::ostringstream ss;
426	  ss << best_name << "+0x" << std::hex << off;
427	  return ss.str();
428	}
