430	std::pair<uint64_t, uint64_t> fn_range(const std::string& elf_path, uint64_t addr) {
431	  std::vector<char> buf;
432	  Elf64_Ehdr eh;
433	  std::string ignored;
434	  if (!read_elf64_header(elf_path, buf, eh, ignored)) return {0, 0};
435	
436	  uint64_t best_value = 0;
437	  uint64_t best_size = 0;
438	  bool found = false;
439	
440	  for (unsigned i = 0; i < eh.e_shnum; ++i) {
441	    Elf64_Shdr sym_sh;
442	    if (!load(buf, eh.e_shoff + static_cast<size_t>(i) * eh.e_shentsize, sym_sh)) break;
443	    if (sym_sh.sh_type != SHT_SYMTAB || sym_sh.sh_entsize == 0) continue;
444	    const size_t nsym = sym_sh.sh_size / sym_sh.sh_entsize;
445	    for (size_t s = 0; s < nsym; ++s) {
446	      Elf64_Sym sym;
447	      if (!load(buf, sym_sh.sh_offset + s * sym_sh.sh_entsize, sym)) break;
448	      if (sym.st_shndx == SHN_UNDEF) continue;
449	      if (ELF64_ST_TYPE(sym.st_info) != STT_FUNC) continue;
450	      if (sym.st_value > addr) continue;
451	      if (sym.st_size != 0 && addr >= sym.st_value + sym.st_size) continue;
452	      if (found && sym.st_value <= best_value) continue;
453	      best_value = sym.st_value;
454	      best_size = sym.st_size;
455	      found = true;
456	    }
457	  }
458	
459	  if (!found || best_size == 0) return {0, 0};
460	  return {best_value, best_value + best_size};
461	}
