465	// Reader for a drained hybrid_state_v1 file -- the C++ analog of
466	// orchestrator.abi.validate_state_file + hsim._read_state_mcycle. Header-only:
467	// it #includes the shared ABI directly, so mcycle/minstret/flags/vlenb are
468	// struct members with no hand-copied offsets.
469	#ifndef ANDESIM_STATE_HPP
470	#define ANDESIM_STATE_HPP
471	
472	#include <cstdio>
473	#include <vector>
474	#include <string>
475	
476	#include "hybrid/state_abi.h"
477	
478	namespace andes_sim {
479	
480	struct StateFile {
481	  hybrid_state_v1 st{};
482	  std::string error;  // empty => valid; non-empty describes the rejection
483	  bool ok() const { return error.empty(); }
484	};
485	
486	// Read `path` and validate it (in order): byte size == sizeof(hybrid_state_v1),
487	// magic == HYBRID_STATE_MAGIC, version == HYBRID_STATE_VERSION. On any failure
488	// `error` is set and `st` is unspecified; otherwise `st` holds the full state.
489	inline StateFile read_state_file(const std::string& path) {
490	  StateFile r;
491	  std::FILE* f = std::fopen(path.c_str(), "rb");
492	  if (!f) {
493	    r.error = path + ": cannot open";
494	    return r;
495	  }
496	  std::fseek(f, 0, SEEK_END);
497	  const long sz = std::ftell(f);
498	  std::rewind(f);
499	  if (sz != static_cast<long>(sizeof(hybrid_state_v1))) {
500	    r.error = path + ": size " + std::to_string(sz) + " != expected " +
501	              std::to_string(sizeof(hybrid_state_v1));
502	    std::fclose(f);
503	    return r;
504	  }
505	  const size_t n = std::fread(&r.st, 1, sizeof(r.st), f);
506	  std::fclose(f);
507	  if (n != sizeof(r.st)) {
508	    r.error = path + ": short read";
509	    return r;
510	  }
511	
512	  char buf[256];
513	  if (r.st.magic != HYBRID_STATE_MAGIC) {
514	    std::snprintf(buf, sizeof(buf), "%s: magic 0x%08x != expected 0x%08x",
515	                  path.c_str(), r.st.magic, HYBRID_STATE_MAGIC);
516	    r.error = buf;
517	    return r;
518	  }
519	  if (r.st.version != HYBRID_STATE_VERSION) {
520	    std::snprintf(buf, sizeof(buf), "%s: version %u != expected %u",
521	                  path.c_str(), r.st.version, HYBRID_STATE_VERSION);
522	    r.error = buf;
523	    return r;
524	  }
525	  return r;
526	}
