532	// Shared-mmap allocation for andesim.
533	//
534	// The caller asks for `size` bytes; we resolve a backing directory over a
535	// tier list (first fit wins, fit = size + 256 MiB free), allocate a sparse
536	// file with mkstemp+truncate, and print one status line that always names
537	// the chosen tier -- and, when we fell past /dev/shm, why. HSIM_MMAP_DIR
538	// pins a single tier (hard error if it does not fit; no fallback past it).
539	#ifndef ANDESIM_SHM_HPP
540	#define ANDESIM_SHM_HPP
541	
542	#include <functional>
543	#include <string>
544	#include <vector>
545	
546	namespace andes_sim {
547	
548	// Free-space headroom a tier must have beyond the requested size.
549	inline constexpr long long kMmapSafetyMargin = 256LL * 1024 * 1024;
550	
551	// One backing-store candidate: the directory plus the label used in
552	// status/error messages ("/dev/shm", "~/.cache/andesim", "HSIM_MMAP_DIR=..").
553	struct MmapTier {
554	  std::string dir;
555	  std::string label;
556	};
557	
558	// resolve_mmap_dir result: the chosen dir ("" on failure) and, when a tier
559	// was skipped, a human note saying which and why ("" when tiers[0] fit).
560	struct MmapDirChoice {
561	  std::string dir;
562	  std::string note;
563	};
564	
565	// Parse "8G" / "512M" / "1024" / "1.5G" into a positive byte count. On success
566	// returns the count and leaves `err` empty; on failure returns 0 and sets `err`
567	// to the argparse-style message. Mirrors hsim_shm.parse_size (fractional values
568	// truncate, like Python int(float(num) * mult)).
569	long long parse_size(const std::string& spec, std::string& err);
570	
571	// L26/F2: the physical shared mmap is one V-scratch page (HYBRID_V_SCRATCH_BYTES)
572	// larger than the program's --mem-size, so the V-register transport page sits
573	// just ABOVE the program's declared RAM. No program layout -- low stack, top-of-
574	// RAM stack, or a heap grown to the ceiling -- can reach a page past its own
575	// RAM, so the scratch can never be clobbered. The vsim side parks the scratch
576	// at the mmap's top page (v_scratch_gpa), which equals ram_base + program_bytes.
577	long long physical_mmap_bytes(long long program_bytes);
578	
579	// The largest --mem-size whose physical mmap still fits the 2 GiB AE350 DRAM
580	// window (program_bytes + scratch page <= 2 GiB). --mem-size is capped here.
581	long long max_program_mem_bytes();
582	
583	// First-fit resolver over `tiers`. `probe(dir)` returns the dir's free bytes,
584	// or -1 when it does not exist. A tier fits when probe >= size + margin.
585	// On success `err` is empty; when nothing fits, returns {"", ""} and `err`
586	// names every tier's reason plus the HSIM_MMAP_DIR hint. Pure: no env, no
587	// filesystem -- testable with a fake probe.
588	MmapDirChoice resolve_mmap_dir(
589	    const std::vector<MmapTier>& tiers, long long size,
590	    const std::function<long long(const std::string&)>& probe,
591	    std::string& err);
592	
593	// Build the real tier list from the environment:
594	//   HSIM_MMAP_DIR set -> that single pinned tier;
595	//   else            -> /dev/shm, then $XDG_CACHE_HOME|~/.cache + /andesim
596	//                      (created here so the free-space probe can see it).
597	std::vector<MmapTier> mmap_tiers();
598	
599	// WSL2 advice for `doctor`: given /proc/version contents, the repo dir, and
600	// the mmap tier list, return warning lines. Empty when not on WSL2. On WSL2:
601	// always the .wslconfig memory= hint (tmpfs is capped by the WSL VM), plus a
602	// drvfs warning for the repo or any tier dir under /mnt/ (slow, and
603	// MAP_SHARED is not coherent across the 9p boundary). Pure -- testable.
604	std::vector<std::string> wsl_warnings(const std::string& proc_version,
605	                                      const std::string& repo_dir,
606	                                      const std::vector<MmapTier>& tiers);
607	
608	// Convert a --mem-size spec into the fast leg's plain QEMU `-m` argv:
609	// {"-m", "<MiB>M"}. Empty spec -> {} with no error (QEMU as-is). Malformed
610	// specs and sizes that are not a whole MiB (QEMU's -m granularity) return {}
611	// and set `err`.
612	std::vector<std::string> qemu_m_args(const std::string& spec, std::string& err);
613	
614	// Allocate a sparse mmap file of `size` bytes in the resolved dir (mkstemp +
615	// truncate), print one "[hsim mmap] <size> at <dir> (free: <free>)" line
616	// (plus "; fallback: <why>" when /dev/shm was skipped), and return its path.
617	// On failure returns "" and sets `err`. Caller owns the file (unlink when
618	// done).
619	std::string allocate(long long size, std::string& err,
620	                     const std::string& prefix = "hsim-shm.");
