645	// Free bytes on the filesystem holding `dir`, or -1 if it does not exist.
646	long long free_bytes(const std::string& dir) {
647	  struct statvfs vfs;
648	  if (statvfs(dir.c_str(), &vfs) != 0) return -1;
649	  return static_cast<long long>(vfs.f_bavail) *
650	         static_cast<long long>(vfs.f_frsize);
651	}
652	
653	// Human-readable byte count: "8.0 GiB", "512.0 MiB", "1024 B". Mirrors
654	// hsim_shm._format_bytes (one decimal, TiB/GiB/MiB/KiB, else "N B").
655	std::string format_bytes(long long n) {
656	  struct Unit {
657	    const char* suffix;
658	    long long mul;
659	  };
660	  static const Unit units[] = {
661	      {"TiB", 1024LL * 1024 * 1024 * 1024},
662	      {"GiB", 1024LL * 1024 * 1024},
663	      {"MiB", 1024LL * 1024},
664	      {"KiB", 1024LL},
665	  };
666	  for (const Unit& u : units) {
667	    if (n >= u.mul) {
668	      char buf[64];
669	      std::snprintf(buf, sizeof(buf), "%.1f %s",
670	                    static_cast<double>(n) / static_cast<double>(u.mul),
671	                    u.suffix);
672	      return buf;
673	    }
674	  }
675	  return std::to_string(n) + " B";
676	}
