680	long long parse_size(const std::string& spec, std::string& err) {
681	  static const std::regex re(R"(\s*(\d+(?:\.\d+)?)\s*([KMGT]?)\s*)",
682	                             std::regex::icase);
683	  std::smatch m;
684	  if (!std::regex_match(spec, m, re)) {
685	    err = "invalid mmap size '" + spec +
686	          "': expected <number>[K|M|G|T] (e.g. '128M', '8G', '1024')";
687	    return 0;
688	  }
689	  const double num = std::stod(m[1].str());
690	  long long mult = 1;
691	  if (m[2].length()) {
692	    switch (std::toupper(static_cast<unsigned char>(m[2].str()[0]))) {
693	      case 'K': mult = 1024LL; break;
694	      case 'M': mult = 1024LL * 1024; break;
695	      case 'G': mult = 1024LL * 1024 * 1024; break;
696	      case 'T': mult = 1024LL * 1024 * 1024 * 1024; break;
697	    }
698	  }
699	  // Truncate toward zero like Python int(float(num) * multiplier).
700	  const long long size =
701	      static_cast<long long>(num * static_cast<double>(mult));
702	  if (size <= 0) {
703	    err = "invalid mmap size '" + spec + "': must be > 0";
704	    return 0;
705	  }
706	  err.clear();
707	  return size;
708	}
709	
710	// L26/F2: physical mmap = program RAM + one V-scratch page. See shm.hpp.
711	long long physical_mmap_bytes(long long program_bytes) {
712	  return program_bytes + HYBRID_V_SCRATCH_BYTES;
713	}
714	
715	long long max_program_mem_bytes() {
716	  // AE350 DRAM window is 2 GiB; leave room for the scratch page on top.
717	  constexpr long long kAe350DramWindowBytes = 2LL * 1024 * 1024 * 1024;
718	  return kAe350DramWindowBytes - HYBRID_V_SCRATCH_BYTES;
719	}
