721	std::vector<std::string> wsl_warnings(const std::string& proc_version,
722	                                      const std::string& repo_dir,
723	                                      const std::vector<MmapTier>& tiers) {
724	  std::string lower = proc_version;
725	  for (char& c : lower) c = static_cast<char>(std::tolower(
726	      static_cast<unsigned char>(c)));
727	  if (lower.find("microsoft") == std::string::npos) return {};
728	
729	  std::vector<std::string> warns;
730	  warns.push_back(
731	      "WSL2: /dev/shm is capped by the WSL VM memory; raise memory= in "
732	      ".wslconfig if tier 1 is too small");
733	  if (repo_dir.starts_with("/mnt/"))
734	    warns.push_back("repo is under /mnt/ (drvfs): slow, and MAP_SHARED is "
735	                    "not coherent -- keep the repo in the Linux home (~)");
736	  for (const MmapTier& t : tiers)
737	    if (t.dir.starts_with("/mnt/"))
738	      warns.push_back("mmap dir " + t.dir +
