761	MmapDirChoice resolve_mmap_dir(
762	    const std::vector<MmapTier>& tiers, long long size,
763	    const std::function<long long(const std::string&)>& probe,
764	    std::string& err) {
765	  const long long need = size + kMmapSafetyMargin;
766	  std::vector<std::string> reasons;
767	  for (const MmapTier& t : tiers) {
768	    const long long free = probe(t.dir);
769	    if (free >= need) {
770	      err.clear();
771	      std::string note;
772	      for (size_t i = 0; i < reasons.size(); i++)
773	        note += (i ? "; " : "") + reasons[i];
774	      return {t.dir, note};
775	    }
776	    reasons.push_back(free < 0 ? t.label + " missing"
777	                               : t.label + " too small (" +
778	                                     format_bytes(free) + " free)");
779	  }
780	  err = "no mmap directory can hold " + format_bytes(size) +
781	        " + 256 MiB margin: ";
782	  for (size_t i = 0; i < reasons.size(); i++)
783	    err += (i ? "; " : "") + reasons[i];
784	  err += "; set HSIM_MMAP_DIR to a directory with enough free space";
785	  return {"", ""};
786	}
