790	    return {{pinned, "HSIM_MMAP_DIR='" + std::string(pinned) + "'"}};
791	
792	  std::string cache;
793	  if (const char* xdg = std::getenv("XDG_CACHE_HOME"); xdg && xdg[0])
794	    cache = std::string(xdg) + "/andesim";
795	  else if (const char* home = std::getenv("HOME"); home && home[0])
796	    cache = std::string(home) + "/.cache/andesim";
