123	// `run --mode cycle` presentation: spawn the engine, hiding its startup banner
124	// and verbose [info] log (VsimFilter), relaying only the program's own output
125	// and any real diagnostics, then restate the lifted cycle count as andesim's own
126	// one-line result under the [andesim] prefix. The count is printed AFTER the run
127	// (the engine logs it at exit), so it follows the program output. Returns the
128	// engine exit code. Unlike fast's exec_passthrough, the parent stays alive to
129	// filter -- fine, because cycle (without --gdb) is a batch run, not interactive.
130	int run_cycle_clean(const std::vector<std::string>& argv) {
131	  VsimFilter filter;
132	  const int rc = run_line_filtered(
133	      argv, [&filter](int stream, std::string_view line) {
134	        std::FILE* dst = nullptr;
135	        switch (filter.classify(stream, line)) {
136	          case VsimFilter::Dest::kStdout: dst = stdout; break;
137	          case VsimFilter::Dest::kStderr: dst = stderr; break;
138	          case VsimFilter::Dest::kDrop: return;
139	        }
140	        std::fwrite(line.data(), 1, line.size(), dst);
141	        std::fputc('\n', dst);
142	      });
143	  if (const std::optional<uint64_t> c = filter.cycles())
144	    std::printf("[andesim] %llu cycles\n", static_cast<unsigned long long>(*c));
145	  return rc;
146	}
