148	// The standalone spine shared by `fast` and `cycle`: both take a single ELF,
149	// then run the resolved engine standalone with `extra` (model flags the
150	// framework forwards, e.g. fast's -m) followed by the post-`--` args verbatim.
151	// `clean_output` picks how the engine's output is presented: fast inherits the
152	// stdio transparently (exec_passthrough -- an interactive gdbstub / monitor /
153	// semihosting console works unchanged); cycle filters out the engine's banner +
154	// [info] noise and restates the cycle count (run_cycle_clean). Either way the
155	// exit code propagates. The per-model engine + selection are resolved by the
156	// caller; `model` here only labels the positional diagnostics.
157	int run_standalone(const Cli& cli, const EngineDescriptor& eng,
158	                   const char* model, const std::vector<std::string>& extra = {},
159	                   bool clean_output = false) {
160	  if (int rc = check_one_elf(cli, model)) return rc;
161	  // QEMU's -bios flag searches its data directory for relative paths rather
162	  // than the CWD; resolve to absolute so both QEMU and vsim find the ELF.
163	  const std::string elf = abs_elf(cli.positional[0], "--mode " + std::string(model));
164	  if (elf.empty()) return 2;
165	  std::vector<std::string> args = extra;
166	  args.insert(args.end(), cli.passthrough.begin(), cli.passthrough.end());
167	  std::string err;
168	  const std::vector<std::string> argv =
169	      passthrough_argv(eng, "standalone", elf, args, err);
170	  if (!err.empty()) {
171	    std::fprintf(stderr, "andesim run: %s\n", err.c_str());
172	    return 2;
173	  }
174	  // --dry-run: print the exact engine command and stop, spawning nothing -- the
175	  // full qemu/vsim command (incl. -bios <elf> and any post-`--`).
176	  if (cli.dry_run)
177	    return print_dry_run({argv}, {std::string("standalone [") + eng.id + "]"});
178	  return clean_output ? run_cycle_clean(argv) : exec_passthrough(argv);
179	}
