181	// `run --mode fast`: QEMU alone, functional, transparent passthrough. Needs
182	// only the built-in qemu descriptor, so it resolves that directly rather than
183	// discover_engines(), which would spawn a --describe subprocess per Verilator
184	// build only to discard them all here.
185	int run_fast(const Cli& cli) {
186	  // fast is QEMU-only; an explicit engine must name 'qemu64' (rv64) or 'qemu32'.
187	  if (!cli.engine.empty() && cli.engine != kQemuId64 && cli.engine != kQemuId32) {
188	    std::fprintf(stderr,
189	                 "andesim run --mode fast: engine must be 'qemu64' or 'qemu32', "
190	                 "got '%s'\n",
191	                 cli.engine.c_str());
192	    return 2;
193	  }
194	  // --mem-size forwards a plain `-m`; QEMU validates it (as-is, no mmap, no
195	  // default injected). It precedes the post-`--` args, so a user's own -m wins.
196	  std::string err;
197	  std::vector<std::string> extra = qemu_m_args(cli.mem_size, err);
198	  if (!err.empty()) {
199	    std::fprintf(stderr, "andesim run --mode fast: %s\n", err.c_str());
200	    return 2;
201	  }
202	  // --gdb: inject QEMU's built-in GDB stub and pause at startup.
203	  if (cli.gdb) {
204	    const std::string port = cli.gdb_port.empty() ? "1234" : cli.gdb_port;
205	    extra.push_back("-gdb");
206	    extra.push_back("tcp::" + port);
207	    extra.push_back("-S");
208	  }
209	  // Pick rv32 vs rv64. An explicit --engine (qemu32/qemu64) wins; otherwise read
210	  // the ELF's class so an rv32 program lands on qemu-system-riscv32 instead of
211	  // the rv64 default. Warn (do not fail) if an explicit choice contradicts the
212	  // ELF -- the override is the user's call.
213	  const int elf_w = cli.positional.empty() ? 0 : elf_xlen(cli.positional[0]);
214	  int xlen;
215	  if (cli.engine == kQemuId32) xlen = 32;
216	  else if (cli.engine == kQemuId64) xlen = 64;
217	  else xlen = elf_w ? elf_w : 64;  // no explicit engine: follow the ELF (else rv64)
218	  // Only an explicit engine can disagree with the ELF (when none is given, xlen
219	  // == elf_w), so this guard already implies an explicit --engine.
220	  if (elf_w && elf_w != xlen)
221	    std::fprintf(stderr,
222	                 "[andesim] --mode fast: --engine %s is rv%d but the ELF is rv%d "
223	                 "(running as rv%d)\n",
224	                 cli.engine.c_str(), xlen, elf_w, xlen);
225	  return run_standalone(cli, builtin_qemu_arch(xlen), "fast", extra);
226	}
