309	// `run --mode cycle`: one cycle-accurate engine alone, from reset (no QEMU,
310	// no --resume-from-qemu), transparent passthrough -- cycles surface in the
311	// engine's own output. Unlike fast, this must discover the Verilator build(s)
312	// to resolve the engine (explicit --engine, else the sole one).
313	int run_accurate(const Cli& cli) {
314	  // Reject a missing/extra ELF before discovery so a CLI typo does not spawn a
315	  // --describe subprocess per Verilator build only to fail on the argument.
316	  if (int rc = check_one_elf(cli, "cycle")) return rc;
317	  // --mem-size is validated but has nothing to size: the cycle engine always
318	  // models its full DRAM window. Say so instead of silently ignoring it.
319	  if (!cli.mem_size.empty()) {
320	    std::string se;
321	    if (parse_size(cli.mem_size, se); !se.empty()) {
322	      std::fprintf(stderr, "andesim run --mode cycle: --mem-size: %s\n",
323	                   se.c_str());
324	      return 2;
325	    }
326	    std::fprintf(stderr,
327	                 "[andesim] --mem-size: the cycle engine models its full "
328	                 "DRAM window; nothing to size\n");
329	  }
330	  Discovery disc = discover_engines();
331	  std::string err;
332	  const EngineDescriptor* eng =
333	      resolve_accurate_engine(disc.engines, cli.engine, err);
334	  if (!eng) {
335	    std::fprintf(stderr, "andesim run --mode cycle: %s\n", err.c_str());
336	    // Surface why an expected engine may be absent (failed --describe, etc.).
337	    for (const std::string& w : disc.warnings)
338	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
339	    return 2;
340	  }
341	  // The ELF must match the engine's width: an rv32 ELF on an rv64 engine (or
342	  // vice versa) cannot run. Catch it here with a clear message instead of the
343	  // engine's cryptic "not of ELFCLASSxx". check_one_elf above guaranteed a lone
344	  // positional.
345	  if (std::string e = elf_engine_arch_error(cli.positional[0], *eng); !e.empty()) {
346	    std::fprintf(stderr, "andesim run --mode cycle: %s\n", e.c_str());
347	    return 2;
348	  }
349	  // --dry-run previews the standalone command and spawns nothing, so it takes
350	  // precedence over the interactive --gdb path (a dry run launches no debugger).
351	  if (cli.gdb && !cli.dry_run) return run_cycle_gdb(cli, *eng);
352	  // clean_output: hide vsim's banner + [info] log, restate the cycle count under
353	  // [andesim] (fast keeps raw passthrough -- QEMU has no such banner and its
354	  // monitor/gdbstub are interactive).
355	  return run_standalone(cli, *eng, "cycle", /*extra=*/{}, /*clean_output=*/true);
356	}
