578	int cmd_run(const Cli& cli) {
579	  if (cli.model.empty()) {
580	    std::fprintf(stderr,
581	                 "andesim run: --mode fast|cycle|hybrid is required "
582	                 "(pick the composition; see 'andesim run --help')\n");
583	    return 2;
584	  }
585	  if (!find_model(cli.model)) {
586	    std::fprintf(stderr,
587	                 "andesim run: unknown model '%s' (want fast|cycle|hybrid)\n",
588	                 cli.model.c_str());
589	    return 2;
590	  }
591	  if (!cli.gdb_port.empty() && !cli.gdb) {
592	    std::fprintf(stderr, "andesim run: --gdb-port requires --gdb\n");
593	    return 2;
594	  }
595	  // --gdb is an interactive debugging aid; the hybrid handoff runs QEMU1 then
596	  // vsim sequentially in a pipeline and cannot pause for a debugger to attach.
597	  if (cli.gdb && cli.model == "hybrid") {
598	    std::fprintf(stderr,
599	                 "andesim run: --gdb is not supported with --mode hybrid\n");
600	    return 2;
601	  }
602	  // --verify re-runs the workload against a QEMU oracle -- only the hybrid
603	  // composition has a second engine to check.
604	  if (cli.verify && cli.model != "hybrid") {
605	    std::fprintf(stderr,
606	                 "andesim run: --verify requires --mode hybrid (the %s "
607	                 "model has nothing to cross-check)\n",
608	                 cli.model.c_str());
609	    return 2;
610	  }
611	  // Post-`--` args are forwarded verbatim to the engine -- but hybrid has TWO
612	  // legs (a QEMU fast-forward + a vsim measure leg) whose command lines the
613	  // handoff builds itself, so there is no single "the engine" to forward to.
614	  // Reject rather than silently drop (the old behavior) or guess a leg. vsim
615	  // options have dedicated flags (--kanata/--objdump); fast/cycle still forward.
616	  if (!cli.passthrough.empty() && cli.model == "hybrid") {
617	    std::fprintf(stderr,
618	                 "andesim run: --mode hybrid takes no `-- <args>` (the handoff "
619	                 "builds both legs' command lines; use --kanata/--objdump for "
620	                 "vsim options, or --mode fast|cycle to forward to one engine)\n");
621	    return 2;
622	  }
623	  // --trigger / --pc-start / --pc-end delimit the hybrid ROI window. --trigger
624	  // is hybrid-only; --pc-start/--pc-end belong to --trigger pc specifically. Any
625	  // other mode/trigger would SILENTLY drop them and hand back a figure for the
626	  // wrong window (fast/cycle: the whole program; hybrid+marker: the marker
627	  // window), so reject instead of measuring something the user did not ask for.
628	  if (!cli.trigger.empty() && cli.model != "hybrid") {
629	    std::fprintf(stderr,
630	                 "andesim run: --trigger applies only to --mode hybrid "
631	                 "(the ROI delimiter); fast/cycle run the whole program\n");
632	    return 2;
633	  }
634	  if (!cli.pc_end.empty() && cli.trigger != "pc") {
635	    std::fprintf(stderr,
636	                 "andesim run: --pc-end applies only to --mode hybrid "
637	                 "--trigger pc\n");
638	    return 2;
639	  }
640	  if (!cli.pc_start.empty() && cli.trigger != "pc") {
641	    std::fprintf(stderr,
642	                 "andesim run: --pc-start applies only to --mode hybrid "
643	                 "--trigger pc\n");
644	    return 2;
645	  }
646	  if (cli.model == "fast") return run_fast(cli);
647	  if (cli.model == "cycle") return run_accurate(cli);
648	  return run_hybrid(cli);  // model validated above; only hybrid remains
649	}
