21	// The bundled functional engine. QEMU does not implement --describe, so the
22	// descriptor is built in. The standalone (model=fast) run uses qemu's OWN
23	// default behavior as far as possible -- the user's post-`--` args (incl. an
24	// explicit -cpu) still win; only the hybrid fast-leg pins a -cpu. Binary path
25	// honors $VSIM_QEMU, then $QEMU_BIN_DIR (env or config.env), then the legacy
26	// in-tree build. Exposed (engine_registry.hpp) so `run --mode fast` resolves
27	// qemu directly, skipping the per-engine --describe scan whole-registry
28	// discovery would spawn.
29	EngineDescriptor builtin_qemu() {
30	  EngineDescriptor d;
31	  d.id = kQemuId;
32	  d.type = "qemu";
33	  d.kind = "functional";
34	  d.xlen = 64;
35	  d.triggers = {"marker", "pc"};
36	  d.state = {"drain"};
37	  d.source = "built-in";
38	
39	  d.roles = {"standalone", "fast-leg"};
40	  // The hybrid fast-forward leg: load the ELF, drain on the plugin's trigger
41	  // into {state_out}, exit 200. {plugin}/{mmap}/{mmap_size}/{state_out} are
42	  // filled by the plan executor (F6); {trigger} is the plugin comma-suffix
43	  // (empty for marker), folded by leg_trigger_args (F9).
44	  d.invoke.push_back(
45	      {"fast-leg",
46	       {"{bin}", "-object",
47	        "memory-backend-file,id=mem,share=on,mem-path={mmap},size={mmap_size}",
48	        "-machine", "andes_ae350,memory-backend=mem", "-cpu",
49	        "andes-ax45mpv,vlen={vlen}", "-nographic", "-semihosting-config",
50	        "enable=on,target=native", "-bios", "{elf}", "-plugin",
51	        "{plugin},outfile={state_out}{trigger}"}});
52	
53	  // The standalone functional run (model=fast). andes_ae350's generic default
54	  // -cpu hangs C-runtime fixtures, so pin a concrete andes core: the
55	  // vector-capable andes-ax46mpv. We pass NO vlen -- the cpu model's own QEMU
56	  // default applies, so both scalar and vector binaries run out of the box; a
57	  // user who needs a specific width passes it via the post-`--` -cpu (e.g.
58	  // -cpu andes-ax46mpv,vlen=512), which still wins. run_passthrough fills
59	  // {bin}/{elf}.
60	  d.invoke.push_back(
61	      {"standalone",
62	       {"{bin}", "-machine", "andes_ae350", "-cpu", "andes-ax46mpv",
63	        "-nographic", "-semihosting-config", "enable=on,target=native",
64	        "-bios", "{elf}"}});
65	
66	  if (const char* q = std::getenv("VSIM_QEMU"); q && *q)
67	    d.bin_path = q;
68	  else if (std::string qd = config_env_value("QEMU_BIN_DIR"); !qd.empty())
69	    d.bin_path = (fs::path(qd) / "qemu-system-riscv64").string();
70	  else
71	    d.bin_path =
72	        (repo_root() / "build" / "qemu" / "qemu-system-riscv64").string();
73	  return d;
74	}
