78	constexpr int kDescribeTimeoutMs = 5000;
79	
80	bool is_executable_file(const fs::path& p) {
81	  std::error_code ec;
82	  if (!fs::is_regular_file(p, ec)) return false;
83	  return ::access(p.c_str(), X_OK) == 0;
84	}
85	
86	std::string read_file(const fs::path& p) {
87	  std::ifstream f(p, std::ios::binary);
88	  std::ostringstream ss;
89	  ss << f.rdbuf();
90	  return ss.str();
91	}
