93	// Ask one binary to describe itself: try `<bin> --describe`, else read the
94	// <bin>.json sidecar. On success fills `d` and returns true; on failure leaves
95	// a human-readable note in `warn`.
96	bool describe_one(const fs::path& bin, EngineDescriptor& d, std::string& warn) {
97	  RunResult r = run_process({bin.string(), "--describe"}, kDescribeTimeoutMs);
98	  if (!r.spawn_failed && !r.timed_out && r.rc == 0) {
99	    json::Parsed p = json::parse(r.out);
100	    if (p.ok) {
101	      std::string err = descriptor_from_json(p.value, d);
102	      if (err.empty()) {
103	        d.bin_path = bin.string();
104	        d.source = "--describe";
105	        return true;
106	      }
107	      warn = bin.string() + ": --describe JSON invalid: " + err;
108	    } else {
109	      warn = bin.string() + ": --describe output is not JSON: " + p.error;
110	    }
111	  }
112	
113	  fs::path sidecar = bin;
114	  sidecar += ".json";
115	  std::error_code ec;
116	  if (fs::exists(sidecar, ec)) {
117	    json::Parsed p = json::parse(read_file(sidecar));
118	    if (p.ok) {
119	      EngineDescriptor sd;
120	      std::string err = descriptor_from_json(p.value, sd);
121	      if (err.empty()) {
122	        sd.bin_path = bin.string();
123	        sd.source = "sidecar";
124	        d = std::move(sd);
125	        return true;
126	      }
127	      warn = sidecar.string() + ": invalid descriptor: " + err;
128	    } else {
129	      warn = sidecar.string() + ": not JSON: " + p.error;
130	    }
131	  }
132	
133	  if (warn.empty()) warn = bin.string() + ": no --describe and no sidecar";
134	  return false;
135	}
