137	// `prefix` filters candidate basenames; empty accepts any executable. The
138	// default verilator/build scan passes "sim_"; a user-curated engines dir passes
139	// "" so a drop-in alioth/sid (any name) is eligible. The naming convention thus
140	// lives in the call site, not in this engine-agnostic scanner.
141	void scan_dir(const fs::path& dir, std::string_view prefix, Discovery& out,
142	              std::set<std::string>& seen) {
143	  std::error_code ec;
144	  if (!fs::is_directory(dir, ec)) return;
145	
146	  std::vector<fs::path> entries;
147	  for (const auto& e : fs::directory_iterator(dir, ec)) entries.push_back(e.path());
148	  std::sort(entries.begin(), entries.end());  // stable, deterministic order
149	
150	  for (const fs::path& p : entries) {
151	    if (!prefix.empty() && !p.filename().string().starts_with(prefix)) continue;
152	    if (!is_executable_file(p)) continue;
153	    EngineDescriptor d;
154	    std::string warn;
155	    if (describe_one(p, d, warn)) {
156	      normalize_engine_label(d);  // verilator -> vsim, before dedup keys on id
157	      if (seen.insert(d.id).second) out.engines.push_back(std::move(d));
158	    } else if (!warn.empty()) {
159	      out.warnings.push_back(warn);
160	    }
161	  }
162	}
163	
164	}  // namespace
