166	// See engine_registry.hpp. VSIM_BIN_DIR (the external prebuilt vsim build,
167	// mirroring QEMU_BIN_DIR) resolved env-first then from config.env, so the driver
168	// finds the external vsim without a prior `source ./setup.sh`; only an
169	// unset-everywhere value falls back to the legacy in-tree build dir.
170	fs::path vsim_scan_dir() {
171	  if (std::string v = config_env_value("VSIM_BIN_DIR"); !v.empty()) return v;
172	  return repo_root() / "verilator" / "build";
173	}
174	
175	Discovery discover_engines() {
176	  Discovery out;
177	  std::set<std::string> seen;
178	
179	  EngineDescriptor qemu = builtin_qemu();
180	  seen.insert(qemu.id);
181	  out.engines.push_back(std::move(qemu));
182	
183	  if (const char* env = std::getenv("ANDESIM_ENGINES_DIR"); env && *env) {
184	    std::stringstream ss(env);
185	    std::string dir;
186	    while (std::getline(ss, dir, ':'))
187	      if (!dir.empty()) scan_dir(dir, /*prefix=*/"", out, seen);
188	  } else {
189	    scan_dir(vsim_scan_dir(), /*prefix=*/"sim_", out, seen);
190	  }
191	  return out;
192	}
