8	Trigger hybrid_trigger(const Cli& cli, const std::string& elf,
9	                       std::string& err) {
10	  err.clear();
11	  const std::string kind = cli.trigger.empty() ? "csr" : cli.trigger;
12	
13	  if (kind == "csr") return {"csr", {}};  // markers in the workload; no params
14	
15	  if (kind == "pc") {
16	    if (cli.pc_start.empty() || cli.pc_end.empty()) {
17	      err = "trigger pc requires --pc-start and --pc-end "
18	            "(a symbol name or 0x address)";
19	      return {};
20	    }
21	    std::string e1, e2;
22	    const std::string enter = resolve_pc(elf, cli.pc_start, e1);
23	    if (!e1.empty()) { err = e1; return {}; }
24	    const std::string exit = resolve_pc(elf, cli.pc_end, e2);
25	    if (!e2.empty()) { err = e2; return {}; }
26	    // Store with the 0x prefix the plugin (enter_pc=0x..) and vsim
27	    // (--hybrid-exit-pc 0x..) expect; leg_trigger_args concatenates verbatim.
28	    return {"pc", {{"enter_pc", "0x" + enter}, {"exit_pc", "0x" + exit}}};
29	  }
30	
31	  if (kind == "icount") {
32	    const std::string q = cli.qemu_icount.empty() ? "10000" : cli.qemu_icount;
33	    const std::string v = cli.vsim_icount.empty() ? "5000" : cli.vsim_icount;
34	    return {"icount", {{"qemu_icount", q}, {"vsim_icount", v}}};
35	  }
36	
37	  if (kind == "simpoint") {
38	    err = "trigger simpoint is not yet supported (F11)";
39	    return {};
40	  }
41	
42	  err = "unknown trigger '" + kind + "' (want csr|pc|icount)";
43	  return {};
44	}
45	
46	std::vector<std::string> vsim_extra_args(const Cli& cli, const std::string& kind,
47	                                         std::string& err) {
48	  err.clear();
49	  std::vector<std::string> out;
50	
51	  // kanata ROI visualization first (csr/pc only; objdump rides kanata).
52	  if (!cli.kanata.empty()) {
53	    if (kind != "csr" && kind != "pc") {
54	      err = "--kanata is only supported with trigger csr or pc (got " + kind +
55	            ")";
56	      return {};
57	    }
58	    out.push_back("--kanata");
59	    out.push_back(cli.kanata);
60	    out.push_back("--kanata-roi");
61	    if (!cli.objdump.empty()) {
62	      out.push_back("--objdump");
63	      out.push_back(cli.objdump);
64	    }
65	  } else if (!cli.objdump.empty()) {
66	    err = "--objdump requires --kanata";
67	    return {};
68	  }
69	
70	  // Warmup window last (any trigger; 0/absent contributes nothing).
71	  if (!cli.vsim_warmup_icount.empty() && cli.vsim_warmup_icount != "0") {
72	    out.push_back("--vsim-warmup-icount");
73	    out.push_back(cli.vsim_warmup_icount);
74	  }
75	  return out;
76	}
