1	// Unit tests for hybrid_trigger (F9): CLI selection -> ROI Trigger, including
2	// pc-boundary resolution against a real fixture's .symtab and the icount
3	// defaults. Pure (no spawn). rt_pc_jump.elf defines `phase_b_landing` (0x100042)
4	// and `phase_c` (0x100046). Plain assert-and-count harness.
5	#include <string>
6	#include <vector>
7	
8	#include "cli.hpp"
9	#include "hybrid.hpp"
10	#include "plan.hpp"
11	#include "repo_root.hpp"
12	#include "test_check.hpp"
13	
14	using namespace andes_sim;
15	using andes_sim::test::check_eq;
16	
17	namespace {
18	Cli mk(const std::vector<std::string>& args) { return parse_cli(args); }
19	}  // namespace
20	
21	int main() {
22	  const std::string elf =
23	      (repo_root() / "tests" / "fixtures" / "rt_pc_jump.elf").string();
24	
25	  // No --trigger defaults to csr (the repo's documented default), no params.
26	  {
27	    std::string err;
28	    Trigger t = hybrid_trigger(mk({"run", "--model", "hybrid"}), elf, err);
29	    CHECK(err.empty());
30	    CHECK(t.kind == "csr");
31	    CHECK(t.params.empty());
32	  }
33	
34	  // pc: a symbol start and a 0x end both resolve; stored as 0x-prefixed hex.
35	  {
36	    std::string err;
37	    Trigger t = hybrid_trigger(
38	        mk({"run", "--model", "hybrid", "--trigger", "pc", "--pc-start",
39	            "phase_b_landing", "--pc-end", "0x100046"}),
40	        elf, err);
41	    CHECK(err.empty());
42	    CHECK(t.kind == "pc");
43	    CHECK(t.params.at("enter_pc") == "0x100042");
44	    CHECK(t.params.at("exit_pc") == "0x100046");
45	  }
46	
47	  // pc requires both boundaries.
48	  {
49	    std::string err;
50	    hybrid_trigger(mk({"run", "--model", "hybrid", "--trigger", "pc",
51	                       "--pc-start", "phase_b_landing"}),
52	                   elf, err);
53	    CHECK(!err.empty());
54	  }
55	
56	  // pc with an undefined symbol is an error naming the symbol.
57	  {
58	    std::string err;
59	    hybrid_trigger(mk({"run", "--model", "hybrid", "--trigger", "pc",
60	                       "--pc-start", "nope_sym", "--pc-end", "phase_c"}),
61	                   elf, err);
62	    CHECK(!err.empty());
63	    CHECK(err.find("nope_sym") != std::string::npos);
64	  }
65	
66	  // icount defaults to 10000 (qemu) / 5000 (vsim).
67	  {
68	    std::string err;
69	    Trigger t = hybrid_trigger(
70	        mk({"run", "--model", "hybrid", "--trigger", "icount"}), elf, err);
71	    CHECK(err.empty());
72	    CHECK(t.kind == "icount");
73	    CHECK(t.params.at("qemu_icount") == "10000");
74	    CHECK(t.params.at("vsim_icount") == "5000");
75	  }
76	
77	  // icount honors explicit counts.
78	  {
79	    std::string err;
80	    Trigger t = hybrid_trigger(
81	        mk({"run", "--model", "hybrid", "--trigger", "icount", "--qemu-icount",
82	            "123", "--vsim-icount", "45"}),
83	        elf, err);
84	    CHECK(err.empty());
85	    CHECK(t.params.at("qemu_icount") == "123");
86	    CHECK(t.params.at("vsim_icount") == "45");
87	  }
88	
89	  // simpoint is not wired yet (F11) -- a clear error, not a silent csr fallback.
90	  {
91	    std::string err;
92	    hybrid_trigger(mk({"run", "--model", "hybrid", "--trigger", "simpoint"}),
93	                   elf, err);
94	    CHECK(!err.empty());
95	  }
96	
97	  // An unknown trigger is an error.
98	  {
99	    std::string err;
100	    hybrid_trigger(mk({"run", "--model", "hybrid", "--trigger", "bogus"}), elf,
101	                   err);
102	    CHECK(!err.empty());
103	  }
104	
105	  // --- vsim_extra_args: user-forwarded vsim-leg flags, validated by trigger ---
106	  {
107	    std::string err;
108	    // warmup only -- valid for any trigger.
109	    check_eq(vsim_extra_args(
110	                 mk({"run", "--model", "hybrid", "--vsim-warmup-icount", "50"}),
111	                 "icount", err),
112	             {"--vsim-warmup-icount", "50"}, "warmup");
113	    CHECK(err.empty());
114	    // a 0 (or absent) warmup contributes nothing.
115	    CHECK(vsim_extra_args(
116	              mk({"run", "--model", "hybrid", "--vsim-warmup-icount", "0"}),
117	              "csr", err)
118	              .empty());
119	    CHECK(err.empty());
120	    CHECK(vsim_extra_args(mk({"run", "--model", "hybrid"}), "csr", err).empty());
121	    CHECK(err.empty());
122	
123	    // kanata (csr/pc): --kanata <f> --kanata-roi.
124	    check_eq(
125	        vsim_extra_args(mk({"run", "--model", "hybrid", "--kanata", "k.txt"}),
126	                        "csr", err),
127	        {"--kanata", "k.txt", "--kanata-roi"}, "kanata");
128	    CHECK(err.empty());
129	    // kanata + objdump.
130	    check_eq(vsim_extra_args(mk({"run", "--model", "hybrid", "--kanata",
131	                                 "k.txt", "--objdump", "o.txt"}),
132	                             "pc", err),
133	             {"--kanata", "k.txt", "--kanata-roi", "--objdump", "o.txt"},
134	             "kanata-objdump");
135	    CHECK(err.empty());
136	    // kanata THEN warmup -- the e2e.sh ordering.
137	    check_eq(vsim_extra_args(mk({"run", "--model", "hybrid", "--kanata",
138	                                 "k.txt", "--vsim-warmup-icount", "9"}),
139	                             "csr", err),
140	             {"--kanata", "k.txt", "--kanata-roi", "--vsim-warmup-icount", "9"},
141	             "kanata-warmup");
142	    CHECK(err.empty());
143	
144	    // --kanata is csr/pc only -- rejected under icount.
145	    vsim_extra_args(mk({"run", "--model", "hybrid", "--kanata", "k.txt"}),
146	                    "icount", err);
147	    CHECK(!err.empty());
148	    // --objdump requires --kanata.
149	    vsim_extra_args(mk({"run", "--model", "hybrid", "--objdump", "o.txt"}),
150	                    "csr", err);
151	    CHECK(!err.empty());
152	  }
153	
154	  return andes_sim::test::report("hybrid");
155	}
