1	// Unit tests for hybrid_trigger (F9): CLI selection -> ROI Trigger, including
2	// pc-boundary resolution against a real fixture's .symtab. Pure (no spawn).
3	// rt_pc_jump.elf defines `phase_b_landing` (0x100042) and `phase_c`
4	// (0x100046). Plain assert-and-count harness.
5	#include <string>
6	#include <vector>
7	
8	#include "cli.hpp"
9	#include "engine_descriptor.hpp"
10	#include "hybrid.hpp"
11	#include "plan.hpp"
12	#include "repo_root.hpp"
13	#include "test_check.hpp"
14	
15	using namespace andes_sim;
16	using andes_sim::test::check_eq;
17	
18	namespace {
19	Cli mk(const std::vector<std::string>& args) { return parse_cli(args); }
20	}  // namespace
21	
22	int main() {
23	  const std::string elf =
24	      (repo_root() / "tests" / "fixtures" / "rt_pc_jump.elf").string();
25	
26	  // --- hybrid_hw_check: ISA sync guard -- the fast leg (QEMU) is rv64 ---
27	  {
28	    EngineDescriptor d;  // an rv32 engine (e.g. vsim:d23) cannot pair with it
29	    d.id = "vsim:d23";
30	    d.xlen = 32;
31	    const std::string err = hybrid_hw_check(d);
32	    CHECK(!err.empty());
33	    CHECK(err.find("vsim:d23") != std::string::npos);
34	    CHECK(err.find("rv64") != std::string::npos);
35	  }
36	  {
37	    EngineDescriptor d;  // matching xlen passes
38	    d.id = "vsim:ax45mpv_premium";
39	    d.xlen = 64;
40	    CHECK(hybrid_hw_check(d).empty());
41	  }
42	  {
43	    EngineDescriptor d;  // an engine that reports no xlen is accepted as-is
44	    d.id = "vsim:x";
45	    CHECK(hybrid_hw_check(d).empty());
46	  }
47	
48	  // --trigger is REQUIRED for hybrid: there is no silent marker default. (It
49	  // used to default to marker, which masked running an unmarked ELF -- the fast
50	  // leg then ran to completion instead of draining at the ROI boundary, and the
51	  // user only saw a cryptic "expected exit 200, got 0".)
52	  {
53	    std::string err;
54	    hybrid_trigger(mk({"run", "--mode", "hybrid"}), elf, err);
55	    CHECK(!err.empty());
56	    CHECK(err.find("--trigger") != std::string::npos);
57	  }
58	
59	  // marker stays a valid EXPLICIT choice (no params).
60	  {
61	    std::string err;
62	    Trigger t = hybrid_trigger(
63	        mk({"run", "--mode", "hybrid", "--trigger", "marker"}), elf, err);
64	    CHECK(err.empty());
65	    CHECK(t.kind == "marker");
66	    CHECK(t.params.empty());
67	  }
68	
69	  // pc: a symbol start and a 0x end both resolve; stored as 0x-prefixed hex.
70	  {
71	    std::string err;
72	    Trigger t = hybrid_trigger(
73	        mk({"run", "--mode", "hybrid", "--trigger", "pc", "--pc-start",
74	            "phase_b_landing", "--pc-end", "0x100046"}),
75	        elf, err);
76	    CHECK(err.empty());
77	    CHECK(t.kind == "pc");
78	    CHECK(t.params.at("enter_pc") == "0x100042");
79	    CHECK(t.params.at("exit_pc") == "0x100046");
80	  }
81	
82	  // pc requires both boundaries.
83	  {
84	    std::string err;
85	    hybrid_trigger(mk({"run", "--mode", "hybrid", "--trigger", "pc",
86	                       "--pc-start", "phase_b_landing"}),
87	                   elf, err);
88	    CHECK(!err.empty());
89	  }
90	
91	  // A zero-length ROI (enter == exit) is rejected: vsim resumes at the enter
92	  // PC and the exit trigger fires on that very instruction, so the window
93	  // measures nothing. Same symbol on both ends.
94	  {
95	    std::string err;
96	    hybrid_trigger(mk({"run", "--mode", "hybrid", "--trigger", "pc",
97	                       "--pc-start", "phase_c", "--pc-end", "phase_c"}),
98	                   elf, err);
99	    CHECK(!err.empty());
100	    CHECK(err.find("same address") != std::string::npos);
101	  }
102	
103	  // Equality is NUMERIC, not textual: a 0x address with leading zeros and the
104	  // symbol at that address are different strings but the same PC -- still an
105	  // empty ROI. (phase_c == 0x100046.)
106	  {
107	    std::string err;
108	    hybrid_trigger(mk({"run", "--mode", "hybrid", "--trigger", "pc",
109	                       "--pc-start", "0x00100046", "--pc-end", "phase_c"}),
110	                   elf, err);
111	    CHECK(!err.empty());
112	    CHECK(err.find("same address") != std::string::npos);
113	  }
114	
115	  // pc with an undefined symbol is an error naming the symbol.
116	  {
117	    std::string err;
118	    hybrid_trigger(mk({"run", "--mode", "hybrid", "--trigger", "pc",
119	                       "--pc-start", "nope_sym", "--pc-end", "phase_c"}),
120	                   elf, err);
121	    CHECK(!err.empty());
122	    CHECK(err.find("nope_sym") != std::string::npos);
123	  }
124	
125	  // icount/simpoint were removed: they now report as unknown triggers, not a
126	  // silent marker fallback.
127	  {
128	    std::string err;
129	    hybrid_trigger(mk({"run", "--mode", "hybrid", "--trigger", "icount"}), elf,
130	                   err);
131	    CHECK(!err.empty());
132	    hybrid_trigger(mk({"run", "--mode", "hybrid", "--trigger", "simpoint"}),
133	                   elf, err);
134	    CHECK(!err.empty());
135	  }
136	
137	  // An unknown trigger is an error.
138	  {
139	    std::string err;
140	    hybrid_trigger(mk({"run", "--mode", "hybrid", "--trigger", "bogus"}), elf,
141	                   err);
142	    CHECK(!err.empty());
143	  }
144	
145	  // --- vsim_extra_args: user-forwarded vsim-leg flags, validated by trigger ---
146	  {
147	    std::string err;
148	    // no forwarded flags -- empty.
149	    CHECK(vsim_extra_args(mk({"run", "--mode", "hybrid"}), "marker", err).empty());
150	    CHECK(err.empty());
151	
152	    // kanata (marker/pc): --kanata <f> --kanata-roi.
153	    check_eq(
154	        vsim_extra_args(mk({"run", "--mode", "hybrid", "--kanata", "k.txt"}),
155	                        "marker", err),
156	        {"--kanata", "k.txt", "--kanata-roi"}, "kanata");
157	    CHECK(err.empty());
158	    // kanata + objdump.
159	    check_eq(vsim_extra_args(mk({"run", "--mode", "hybrid", "--kanata",
160	                                 "k.txt", "--objdump", "o.txt"}),
161	                             "pc", err),
162	             {"--kanata", "k.txt", "--kanata-roi", "--objdump", "o.txt"},
163	             "kanata-objdump");
164	    CHECK(err.empty());
165	
166	    // --kanata is marker/pc only -- rejected under any other kind.
167	    vsim_extra_args(mk({"run", "--mode", "hybrid", "--kanata", "k.txt"}),
168	                    "bogus", err);
169	    CHECK(!err.empty());
170	    // --objdump requires --kanata.
171	    vsim_extra_args(mk({"run", "--mode", "hybrid", "--objdump", "o.txt"}),
172	                    "marker", err);
173	    CHECK(!err.empty());
174	  }
175	
176	  return andes_sim::test::report("hybrid");
177	}
