1	// Unit tests for resolve_pc (F9): the pc-trigger boundary resolver. A boundary
2	// is either a "0x"-prefixed hex address (used verbatim, prefix stripped) or a
3	// symbol name looked up in the ELF .symtab -> st_value. C++ port of
4	// tests/lib/roi.sh:resolve_pc, but reading the symtab directly (no `nm`).
5	//
6	// Fixtures are real built ELFs: handoff_roundtrip.elf defines `_start` at
7	// 0x100000 (a stable linker-script entry). Plain assert-and-count harness.
8	#include <elf.h>
9	
10	#include <filesystem>
11	#include <fstream>
12	#include <string>
13	
14	#include "elf_syms.hpp"
15	#include "repo_root.hpp"
16	#include "test_check.hpp"
17	
18	using namespace andes_sim;
19	
20	int main() {
21	  const std::string elf =
22	      (repo_root() / "tests" / "fixtures" / "handoff_roundtrip.elf").string();
23	
24	  // A 0x address resolves to itself with the prefix stripped (verbatim, no
25	  // symtab touched) -- matches roi.sh `${boundary#0[xX]}`.
26	  {
27	    std::string err;
28	    CHECK(resolve_pc(elf, "0x100000", err) == "100000");
29	    CHECK(err.empty());
30	  }
31	  // 0X (capital) prefix is also stripped; the remaining digits are kept as-is.
32	  {
33	    std::string err;
34	    CHECK(resolve_pc(elf, "0X1ABC", err) == "1ABC");
35	    CHECK(err.empty());
36	  }
37	  // A defined symbol resolves to its st_value as bare lowercase hex.
38	  {
39	    std::string err;
40	    CHECK(resolve_pc(elf, "_start", err) == "100000");
41	    CHECK(err.empty());
42	  }
43	  // An undefined symbol is a hard error (empty result + message naming it).
44	  {
45	    std::string err;
46	    CHECK(resolve_pc(elf, "definitely_not_a_symbol_xyz", err).empty());
47	    CHECK(!err.empty());
48	    CHECK(err.find("definitely_not_a_symbol_xyz") != std::string::npos);
49	  }
50	  // A 0x prefix with non-hex characters is malformed, NOT a silent verbatim
51	  // pass: returning "ZZZ"/"10zz" lets the downstream strtoull truncate them to
52	  // 0x0 / 0x10, so the hybrid run silently measures the wrong PC window.
53	  {
54	    std::string err;
55	    CHECK(resolve_pc(elf, "0xZZZ", err).empty());
56	    CHECK(!err.empty());
57	  }
58	  {  // partial-hex: must reject, not keep the valid prefix
59	    std::string err;
60	    CHECK(resolve_pc(elf, "0x10zz", err).empty());
61	    CHECK(!err.empty());
62	  }
63	  // An unreadable ELF is an error, not a crash.
64	  {
65	    std::string err;
66	    CHECK(resolve_pc("/no/such/file.elf", "_start", err).empty());
67	    CHECK(!err.empty());
68	  }
69	
70	  // L26/F3: elf_load_top -- the highest byte of the ELF's static image
71	  // (max p_paddr + p_memsz over PT_LOAD). handoff_roundtrip has one LOAD
72	  // segment at 0x100000; its top sits just past the base and well below any
73	  // realistic --mem-size ceiling, so the driver's scratch-overlap guard never
74	  // false-fires on it.
75	  {
76	    std::string err;
77	    const uint64_t top = elf_load_top(elf, err);
78	    CHECK(err.empty());
79	    CHECK(top > 0x100000ull);          // base + segment content
80	    CHECK(top < 0x00110000ull);        // tiny fixture: within 64 KiB of base
81	    // Clearance decision the driver makes: image must end at/below the scratch
82	    // GPA (= ram_base + program_mem). Fits a 128 MiB program, overlaps a 1 MiB.
83	    CHECK(top <= 128ull * 1024 * 1024);     // 128M ceiling -> OK
84	    CHECK(top > 1ull * 1024 * 1024);        // 1M ceiling   -> would overlap
85	  }
86	  // An unreadable / non-ELF file is an error (0 + message), not a crash.
87	  {
88	    std::string err;
89	    CHECK(elf_load_top("/no/such/file.elf", err) == 0u);
90	    CHECK(!err.empty());
91	  }
92	
93	  // elf_xlen: the ELF class width (rv32/rv64) from e_ident. Source of truth for
94	  // the fast auto-pick and the cycle/hybrid arch-match guard (F1).
95	  {
96	    namespace fs = std::filesystem;
97	    // Real rv64 fixture -> 64.
98	    CHECK(elf_xlen(elf) == 64);
99	    // Fabricated rv32 e_ident (ELFMAG + ELFCLASS32) -> 32. Proves the 32 path
100	    // with no rv32 toolchain / fixture (those arrive in F3).
101	    const std::string p32 =
102	        (fs::temp_directory_path() / "andesim_elf_xlen_rv32.bin").string();
103	    {
104	      unsigned char ident[EI_NIDENT] = {ELFMAG0, ELFMAG1, ELFMAG2, ELFMAG3,
105	                                        ELFCLASS32};
106	      std::ofstream(p32, std::ios::binary | std::ios::trunc)
107	          .write(reinterpret_cast<const char*>(ident), sizeof(ident));
108	    }
109	    CHECK(elf_xlen(p32) == 32);
110	    fs::remove(p32);
111	    // Non-ELF and missing -> 0 (no crash, no false width).
112	    const std::string pg =
113	        (fs::temp_directory_path() / "andesim_elf_xlen_garbage.bin").string();
114	    { std::ofstream(pg, std::ios::binary | std::ios::trunc) << "not an elf"; }
115	    CHECK(elf_xlen(pg) == 0);
116	    fs::remove(pg);
117	    CHECK(elf_xlen("/no/such/file.elf") == 0);
118	  }
119	
120	  return andes_sim::test::report("elf-syms");
121	}
