1	// The phase-plan grammar driven by run_plan (F6) -- the C++ analog of
2	// orchestrator/plan.py's Session/Step model, minus the dropped QEMU2 step.
3	//
4	// A Plan is a list of Steps; each Step names an engine (by id, resolved against
5	// the F2 registry), the role to invoke it in (its `invoke` template key, e.g.
6	// "fast-leg" / "accurate-leg"), and a Trigger. run_plan spawns each leg in
7	// order, threads the drained hybrid_state_v1 file forward, and returns each
8	// leg's mcycle/minstret. Under the no-QEMU2-handback design every F6 step
9	// drains, so the hybrid cycle figure is the vsim-leg mcycle minus the qemu-leg
10	// mcycle.
11	#ifndef ANDES_SIM_PLAN_HPP
12	#define ANDES_SIM_PLAN_HPP
13	
14	#include <map>
15	#include <string>
16	#include <vector>
17	
18	namespace andes_sim {
19	
20	// The ROI delimiter for a step. `kind` is csr|pc|icount|simpoint; `params`
21	// carries kind-specific values (e.g. icount=N, enter_pc, exit_pc) that F9 maps
22	// onto trigger args. F6 only exercises the default csr case (no params).
23	struct Trigger {
24	  std::string kind;
25	  std::map<std::string, std::string> params;
26	};
27	
28	// One leg of a plan: which engine, which invoke role, under which trigger.
29	// `extra_args` are verbatim tokens appended after the filled template and the
30	// trigger args -- the seam for user-forwarded per-leg flags (e.g. the vsim
31	// leg's --vsim-warmup-icount / --kanata), which are orthogonal to the trigger.
32	struct Step {
33	  std::string engine_id;  // "qemu" | "verilator:ax45mpv_premium"
34	  std::string role;       // invoke-template key: "fast-leg" | "accurate-leg"
35	  Trigger trigger;
36	  std::vector<std::string> extra_args{};  // default-init: keeps 3-field Step{} literals warning-free
37	};
38	
39	// A whole hybrid run. Every step loads `elf`; the shared mmap (`mem_size`
40	// bytes, at `mmap_path` or allocated by run_plan when empty) survives across
41	// every leg so memory threads through.
42	struct Plan {
43	  std::string elf;          // path to the ELF every leg launches
44	  long long mem_size = 0;   // shared-mmap size in bytes
45	  std::string mmap_path;    // "" => run_plan allocates one (F5) and owns it
46	  std::vector<Step> steps;
47	};
48	
49	// What one drain step measured (read back from its state file).
50	struct PhaseResult {
51	  unsigned long long mcycle = 0;
52	  unsigned long long minstret = 0;
53	};
54	
55	// Aggregate outcome. `error` empty => every step matched its expected exit and
56	// drained a valid state file; `phases` then holds one entry per step in order.
57	struct PlanResult {
58	  std::string error;
59	  std::vector<PhaseResult> phases;
60	  bool ok() const { return error.empty(); }
61	};
62	
63	}  // namespace andes_sim
64	
65	#endif  // ANDES_SIM_PLAN_HPP
66

1	// `andes-sim run --model fast|accurate|hybrid [engine selection] ELF [-- engine args]`.
2	//
3	// The top selection axis. F7/F8 land the two standalone models, `fast` (QEMU)
4	// and `accurate` (a cycle-accurate engine, from reset): each resolves its
5	// engine, then hands off to transparent passthrough -- the ELF plus everything
6	// after `--` becomes the engine's own command line, run with inherited stdio,
7	// no timeout, and the exit code propagated, so a gdbstub / monitor /
8	// semihosting console all behave as if the engine were invoked directly.
9	// `hybrid` (F9) orchestrates a QEMU1 -> vsim handoff via run_plan and prints the
10	// window-cycle figure (the vsim mcycle delta).
11	#include <cstdio>
12	#include <filesystem>
13	#include <string>
14	
15	#include "cli.hpp"
16	#include "engine_descriptor.hpp"
17	#include "engine_registry.hpp"
18	#include "hybrid.hpp"
19	#include "models.hpp"
20	#include "plan.hpp"
21	#include "run_passthrough.hpp"
22	#include "run_plan.hpp"
23	#include "shm.hpp"
24	
25	namespace fs = std::filesystem;
26	
27	namespace andes_sim {
28	namespace {
29	
30	// Validate the lone-ELF positional shape the standalone models require: print
31	// the diagnostic and return 2 on a violation, else 0. Split out so `accurate`
32	// can reject a missing/extra ELF BEFORE paying for engine discovery (which
33	// spawns a --describe subprocess per Verilator build). `model` labels the error.
34	int check_one_elf(const Cli& cli, const char* model) {
35	  if (cli.positional.empty()) {
36	    std::fprintf(stderr, "andes-sim run --model %s: missing ELF\n", model);
37	    return 2;
38	  }
39	  if (cli.positional.size() > 1) {
40	    std::fprintf(stderr,
41	                 "andes-sim run --model %s: unexpected argument '%s' "
42	                 "(engine args go after --)\n",
43	                 model, cli.positional[1].c_str());
44	    return 2;
45	  }
46	  return 0;
47	}
48	
49	// The standalone-passthrough spine shared by `fast` and `accurate`: both take a
50	// single ELF, then exec the resolved engine standalone with the post-`--` args
51	// appended verbatim (inherit stdio, no timeout, propagate exit code). The only
52	// per-model differences -- which engine, and how it is selected -- are resolved
53	// by the caller; `model` here only labels the positional diagnostics.
54	int run_standalone(const Cli& cli, const EngineDescriptor& eng,
55	                   const char* model) {
56	  if (int rc = check_one_elf(cli, model)) return rc;
57	  std::string err;
58	  int rc = run_passthrough(eng, "standalone", cli.positional[0],
59	                           cli.passthrough, err);
60	  if (!err.empty()) std::fprintf(stderr, "andes-sim run: %s\n", err.c_str());
61	  return rc;
62	}
63	
64	// `run --model fast`: QEMU alone, functional, transparent passthrough. Needs
65	// only the built-in qemu descriptor, so it resolves that directly rather than
66	// discover_engines(), which would spawn a --describe subprocess per Verilator
67	// build only to discard them all here.
68	int run_fast(const Cli& cli) {
69	  // fast is QEMU-only; an explicit engine must name it.
70	  if (!cli.engine.empty() && cli.engine != "qemu") {
71	    std::fprintf(stderr,
72	                 "andes-sim run --model fast: engine must be 'qemu', got '%s'\n",
73	                 cli.engine.c_str());
74	    return 2;
75	  }
76	  return run_standalone(cli, builtin_qemu(), "fast");
77	}
78	
79	// `run --model accurate`: one cycle-accurate engine alone, from reset (no QEMU,
80	// no --resume-from-qemu), transparent passthrough -- cycles surface in the
81	// engine's own output. Unlike fast, this must discover the Verilator build(s)
82	// to resolve the engine (explicit --engine, else the sole one).
83	int run_accurate(const Cli& cli) {
84	  // Reject a missing/extra ELF before discovery so a CLI typo does not spawn a
85	  // --describe subprocess per Verilator build only to fail on the argument.
86	  if (int rc = check_one_elf(cli, "accurate")) return rc;
87	  Discovery disc = discover_engines();
88	  std::string err;
89	  const EngineDescriptor* eng =
90	      resolve_accurate_engine(disc.engines, cli.engine, err);
91	  if (!eng) {
92	    std::fprintf(stderr, "andes-sim run --model accurate: %s\n", err.c_str());
93	    // Surface why an expected engine may be absent (failed --describe, etc.).
94	    for (const std::string& w : disc.warnings)
95	      std::fprintf(stderr, "andes-sim: skipped engine: %s\n", w.c_str());
96	    return 2;
97	  }
98	  return run_standalone(cli, *eng, "accurate");
99	}
100	
101	// `run --model hybrid`: orchestrate a QEMU1 fast-forward -> vsim measure+drain
102	// handoff (no QEMU2). The trigger (csr|pc|icount) delimits the ROI; the cycle
103	// figure is the vsim mcycle minus QEMU1's drained mcycle. Replaces the Python
104	// driver's tests/e2e.sh delegation with a single window-cycle line.
105	int run_hybrid(const Cli& cli) {
106	  // Single diagnostic sink for the early-validation returns: prefix + exit 2.
107	  auto fail = [](const std::string& msg) {
108	    std::fprintf(stderr, "andes-sim run --model hybrid: %s\n", msg.c_str());
109	    return 2;
110	  };
111	
112	  if (int rc = check_one_elf(cli, "hybrid")) return rc;
113	
114	  // Resolve to an absolute, existing path: a clean error beats a downstream
115	  // spawn failure, and pc-trigger resolution reads the ELF's .symtab.
116	  std::error_code ec;
117	  const fs::path elf = fs::absolute(cli.positional[0], ec);
118	  if (ec || !fs::is_regular_file(elf, ec))
119	    return fail("ELF not found: " + cli.positional[0]);
120	  const std::string elf_path = elf.string();
121	
122	  // Validate everything cheap BEFORE the expensive engine discovery, so a CLI
123	  // mistake fails fast without spawning a --describe per Verilator build.
124	  std::string err;
125	  const Trigger trig = hybrid_trigger(cli, elf_path, err);
126	  if (!err.empty()) return fail(err);
127	
128	  std::vector<std::string> vsim_extras = vsim_extra_args(cli, trig.kind, err);
129	  if (!err.empty()) return fail(err);
130	
131	  long long mem = 128LL * 1024 * 1024;  // shared mmap; --mmap-size overrides
132	  if (!cli.mmap_size.empty()) {
133	    std::string se;
134	    mem = parse_size(cli.mmap_size, se);
135	    if (!se.empty()) return fail("--mmap-size: " + se);
136	  }
137	
138	  // qemu is the built-in fast leg; resolve the accurate (vsim) leg by --engine
139	  // or the sole cycle-accurate engine (reusing the F8 selector).
140	  Discovery disc = discover_engines();
141	  const EngineDescriptor* acc =
142	      resolve_accurate_engine(disc.engines, cli.engine, err);
143	  if (!acc) {
144	    std::fprintf(stderr, "andes-sim run --model hybrid: %s\n", err.c_str());
145	    for (const std::string& w : disc.warnings)
146	      std::fprintf(stderr, "andes-sim: skipped engine: %s\n", w.c_str());
147	    return 2;
148	  }
149	
150	  Plan plan;
151	  plan.elf = elf_path;
152	  plan.mem_size = mem;
153	  Step qemu_step{"qemu", "fast-leg", trig};
154	  Step vsim_step{acc->id, "accurate-leg", trig};
155	  vsim_step.extra_args = std::move(vsim_extras);  // kanata + warmup, validated
156	  plan.steps = {qemu_step, vsim_step};
157	
158	  // Banner to stderr so the window-cycle result stands alone on stdout.
159	  std::fprintf(stderr, "[andes-sim] model=hybrid engine=%s trigger=%s fixture=%s\n",
160	               acc->id.c_str(), trig.kind.c_str(), elf.stem().string().c_str());
161	
162	  const PlanResult r = run_plan(plan, disc.engines);
163	  if (!r.ok()) {
164	    std::fprintf(stderr, "andes-sim run --model hybrid: %s\n", r.error.c_str());
165	    return 1;
166	  }
167	  // phases[0] = QEMU1 drain, [1] = vsim drain; the kernel/window figure is the
168	  // vsim mcycle delta.
169	  const unsigned long long q_mc = r.phases[0].mcycle;
170	  const unsigned long long v_mc = r.phases[1].mcycle;
171	  std::printf("[%s window_cycles] %llu  (vsim mcycle=%llu - qemu mcycle=%llu)\n",
172	              trig.kind.c_str(), v_mc - q_mc, v_mc, q_mc);
173	  std::printf("PASS: --model hybrid --trigger %s (%s)\n", trig.kind.c_str(),
174	              elf.stem().string().c_str());
175	  return 0;
176	}
177	
178	}  // namespace
179	
180	int cmd_run(const Cli& cli) {
181	  if (cli.model.empty()) {
182	    std::fprintf(stderr,
183	                 "andes-sim run: --model fast|accurate|hybrid is required\n");
184	    return 2;
185	  }
186	  if (!find_model(cli.model)) {
187	    std::fprintf(stderr,
188	                 "andes-sim run: unknown model '%s' (want fast|accurate|hybrid)\n",
189	                 cli.model.c_str());
190	    return 2;
191	  }
192	  if (cli.model == "fast") return run_fast(cli);
193	  if (cli.model == "accurate") return run_accurate(cli);
194	  return run_hybrid(cli);  // model validated above; only hybrid remains
195	}
