1	// Shared-mmap allocation -- a C++ port of tools/hsim_shm.py. See shm.hpp.
2	#include "shm.hpp"
3	
4	#include <cctype>
5	#include <cstdio>
6	#include <cstdlib>
7	#include <regex>
8	#include <vector>
9	
10	#include <sys/stat.h>
11	#include <sys/statvfs.h>
12	#include <unistd.h>
13	
14	namespace andes_sim {
15	namespace {
16	
17	constexpr long long kSafetyMargin = 256LL * 1024 * 1024;  // 256 MiB headroom
18	
19	// Free bytes on the filesystem holding `dir`, or -1 if statvfs fails.
20	long long free_bytes(const std::string& dir) {
21	  struct statvfs vfs;
22	  if (statvfs(dir.c_str(), &vfs) != 0) return -1;
23	  return static_cast<long long>(vfs.f_bavail) *
24	         static_cast<long long>(vfs.f_frsize);
25	}
26	
27	// Human-readable byte count: "8.0 GiB", "512.0 MiB", "1024 B". Mirrors
28	// hsim_shm._format_bytes (one decimal, TiB/GiB/MiB/KiB, else "N B").
29	std::string format_bytes(long long n) {
30	  struct Unit {
31	    const char* suffix;
32	    long long mul;
33	  };
34	  static const Unit units[] = {
35	      {"TiB", 1024LL * 1024 * 1024 * 1024},
36	      {"GiB", 1024LL * 1024 * 1024},
37	      {"MiB", 1024LL * 1024},
38	      {"KiB", 1024LL},
39	  };
40	  for (const Unit& u : units) {
41	    if (n >= u.mul) {
42	      char buf[64];
43	      std::snprintf(buf, sizeof(buf), "%.1f %s",
44	                    static_cast<double>(n) / static_cast<double>(u.mul),
45	                    u.suffix);
46	      return buf;
47	    }
48	  }
49	  return std::to_string(n) + " B";
50	}
51	
52	}  // namespace
53	
54	long long parse_size(const std::string& spec, std::string& err) {
55	  static const std::regex re(R"(\s*(\d+(?:\.\d+)?)\s*([KMGT]?)\s*)",
56	                             std::regex::icase);
57	  std::smatch m;
58	  if (!std::regex_match(spec, m, re)) {
59	    err = "invalid mmap size '" + spec +
60	          "': expected <number>[K|M|G|T] (e.g. '128M', '8G', '1024')";
61	    return 0;
62	  }
63	  const double num = std::stod(m[1].str());
64	  long long mult = 1;
65	  if (m[2].length()) {
66	    switch (std::toupper(static_cast<unsigned char>(m[2].str()[0]))) {
67	      case 'K': mult = 1024LL; break;
68	      case 'M': mult = 1024LL * 1024; break;
69	      case 'G': mult = 1024LL * 1024 * 1024; break;
70	      case 'T': mult = 1024LL * 1024 * 1024 * 1024; break;
71	    }
72	  }
73	  // Truncate toward zero like Python int(float(num) * multiplier).
74	  const long long size =
75	      static_cast<long long>(num * static_cast<double>(mult));
76	  if (size <= 0) {
77	    err = "invalid mmap size '" + spec + "': must be > 0";
78	    return 0;
79	  }
80	  err.clear();
81	  return size;
82	}
83	
84	std::string select_mmap_dir(long long size, std::string& err) {
85	  const char* pinned = std::getenv("HSIM_MMAP_DIR");
86	  const bool have_pin = pinned && pinned[0];
87	  const std::string target = have_pin ? std::string(pinned) : "/dev/shm";
88	  const std::string label =
89	      have_pin ? "HSIM_MMAP_DIR='" + std::string(pinned) + "'"
90	               : "/dev/shm (default)";
91	
92	  struct stat sb;
93	  if (stat(target.c_str(), &sb) != 0 || !S_ISDIR(sb.st_mode)) {
94	    err = "mmap directory does not exist: " + target + " (" + label +
95	          "); set HSIM_MMAP_DIR=/path/to/existing/dir";
96	    return "";
97	  }
98	  const long long free = free_bytes(target);
99	  const long long need = size + kSafetyMargin;
100	  if (free < need) {
101	    err = target + " has " + std::to_string(free) + " bytes free, need " +
102	          std::to_string(need) + " (size=" + std::to_string(size) +
103	          " + 256 MiB margin); set HSIM_MMAP_DIR to a directory with more "
104	          "free space";
105	    return "";
106	  }
107	  err.clear();
108	  return target;
109	}
110	
111	std::string allocate(long long size, std::string& err,
112	                     const std::string& prefix) {
113	  const std::string dir = select_mmap_dir(size, err);
114	  if (dir.empty()) return "";
115	
116	  std::string tmpl = dir + "/" + prefix + "XXXXXX";
117	  std::vector<char> buf(tmpl.begin(), tmpl.end());
118	  buf.push_back('\0');
119	  const int fd = mkstemp(buf.data());
120	  if (fd < 0) {
121	    err = "failed to create mmap file in " + dir;
122	    return "";
123	  }
124	  close(fd);
125	  const std::string path(buf.data());
126	  if (truncate(path.c_str(), size) != 0) {
127	    unlink(path.c_str());
128	    err = "failed to size mmap file " + path;
129	    return "";
130	  }
131	
132	  std::printf("[hsim mmap] %s at %s (free: %s)\n", format_bytes(size).c_str(),
133	              dir.c_str(), format_bytes(free_bytes(dir)).c_str());
134	  std::fflush(stdout);
135	  err.clear();
136	  return path;
137	}
