156	// Per-command `andesim <cmd> --help`: the matching slice of the same tree.
157	void print_subcommand_help(const Subcommand& sc, std::FILE* out) {
158	  if (sc.name == "run") { print_run_block(out); return; }
159	  if (sc.name == "list") { print_list_block(out); return; }
